"""
core/kernel_voice.py — เสียงของ kernel: ตอบได้แม้ไม่มี AI

มี AI ก็ดี ไม่มีก็ต้องมีคำตอบ
- ไม่เรียก LLM ไม่ใช้เน็ต ไม่สุ่ม: input เดิม → คำตอบเดิมทุกครั้ง (Determinism)
- ทุกคำตอบมีทางเลือก ≥ 1 เสมอ (Choice(t) ≥ 1)
- วิกฤตก่อน: ทำร้ายตัวเอง → สายด่วน · อันตรายทางกาย → 1669/191 · ปัจจัยพื้นฐาน → กิน/นอน/ปลอดภัย ก่อน
- ตัวเลขที่แสดงมาจากสมการของระบบ:
      W     = ((100 − E) + R + S) / 3              (โครงสร้าง ×100 — สูตรเดียวกับ quick_assess)
      Risk  = max(0.5E + 0.5(100 − R), risk จากข้อความ)
      Choice(t) = จำนวนทางที่ให้ไป

ใช้: compose(text, route=..., voice_mode=..., pattern=...) → str
"""

