_GROOM_STRANGER = re.compile(r"^(?![\s\S]*(?:ครู|ติวเตอร์|โค้ช|ผู้ฝึกสอน|อาจารย์|พี่เลี้ยง|คนขับรถรับส่ง|\b(?:teacher|tutor|coach|instructor|youth (?:leader|pastor))\b))", re.I)


