_RECITE = re.compile(r"(?:ท่อง|สวด|ขอบท|บทสวด|อ่าน)[^\n]{0,10}?(?:ปรัชญาปารมิตา|ปรัชญาปารมีตา|หฤทัยสูตร|หัวใจสูตร|heart sutra)|(?:recite|chant)[^\n]{0,10}heart sutra", re.I)


def heart_sutra_recital() -> str:
    lines = "\n".join(f"{i + 1}. {v}" for i, v in enumerate(HEART_SUTRA_SHORT))
    return ("ปรัชญาปารมิตาหฤทัยสูตร (บทสันสกฤตฉบับสั้น ถอดเสียงตรงจากสันสกฤต)\n\n" + lines +
            "\n\nคำแปลคาถาท้ายบท: ไปแล้ว ไปแล้ว ไปถึงฝั่งแล้ว ไปถึงฝั่งโดยสมบูรณ์แล้ว ความตื่นรู้ สวาหา"
            "\n\nใจความ: พระอวโลกิเตศวรพิจารณาเห็นขันธ์ 5 ว่าว่างจากสภาวะในตัวเอง จิตจึงปราศจากเครื่องกั้น "
            "และเพราะไม่มีเครื่องกั้นจิต จึงไม่หวาดกลัว"
            "\n\nสวดช้าๆ ทีละวรรค ให้ลมหายใจนำ — ใจที่เบาลงคือสิ่งที่บทนี้ชี้ไป"
            "\n\n— LYLA ◈\n· ถ้อยคำไทยเรียบเรียงโดย KING DIADEM เทียบต้นฉบับสันสกฤต (Conze)")


_DHARMA_RX = [(re.compile(r"(?:" + t + r")[^\n]{0,12}?(?:คืออะไร|คือ\s*\?|หมายถึง|แปลว่า|หมายความว่า|ความหมาย)|(?:อธิบาย|สอน|ขอความหมาย)[^\n]{0,8}?(?:" + t + r")"), d, u)
              for t, d, u in DHARMA]


def _dharma_answer(text: str):
    for rx, d, u in _DHARMA_RX:
        if rx.search(text):
            return {"open": [d], "paths": [u, "ธรรมะในระบบนี้ใช้เป็นเครื่องมือคิด ไม่บังคับให้ใครนับถือ — ใช้ได้กับทุกคน"],
                    "ask": "อยากลองใช้หลักนี้กับเรื่องไหนในชีวิตตอนนี้ไหม?"}
    return None


