# หัวข้อกว้างที่ตอบผิดเรื่องจนต้องตัดทิ้ง — ที่เหลือแค่เลื่อนไปไว้หลังหัวข้อเฉพาะ (ยังนับว่าเป็นเรื่องติดพนัน/ฉุกเฉินอยู่)
