_WITHDRAWAL = re.compile(r"(?:เลิก|หยุด|ขาด)(?:เหล้า|สุรา|ดื่ม)[^\n]{0,24}?(?:ลงแดง|มือสั่น|ตัวสั่น|ชัก|เห็นภาพหลอน|ประสาทหลอน|เหงื่อแตก)|"
                         r"(?:ลงแดง|มือสั่น|ตัวสั่น)[^\n]{0,16}?(?:เลิก|หยุด|ขาด)(?:เหล้า|สุรา|ดื่ม)|ลงแดงเหล้า|"
                         r"\b(?:alcohol withdrawal|withdrawal (?:shakes|seizure)|delirium tremens)\b|\bstopped drinking\b[^\n]{0,30}?\bshak", re.I)
_DENGUE_WARN = re.compile(r"ไข้เลือดออก[^\n]{0,30}?(?:เกล็ดเลือดต่ำ|เลือดออก(?!ก)|ปวดท้อง|อาเจียน|ซึม|มือเท้าเย็น)|\bdengue\b[^\n]{0,30}?\b(?:low platelets?|bleeding|vomiting)\b", re.I)


_MAX_LEN = 8000


_RUN = re.compile(r"(.)\1{12,}", re.S)
_SURR = re.compile("[\ud800-\udfff]")
_INVIS = re.compile("[\u200b-\u200d\u2060\ufeff\u00ad]")
_FULLWIDTH = {c: c - 0xFEE0 for c in range(0xFF01, 0xFF5F)} | {0x3000: 0x20}
_DECOR = re.compile("[\u0334-\u0338\u20d0-\u20ff]")   # เฉพาะขีดทับ — วรรณยุกต์ภาษาอื่น (โยรูบา "fẹ́") ต้องคงไว้


def _clip(text) -> str:
    """ข้อความยาวมาก (80,000 ตัวอักษรเคยใช้ 1.5–3.5 วินาที) — ตรวจหัว 6,000 + ท้าย 2,000 ตัวอักษร
    เรื่องด่วนมักอยู่ต้นหรือท้ายข้อความ จึงไม่ตัดท้ายทิ้ง"""
    text = text if isinstance(text, str) else str(text or "")
    # อักขระครึ่งตัว (surrogate เดี่ยว เช่น "\ud800" จาก JSON) เข้ารหัส UTF-8 ไม่ได้ — เดิมทำให้ตอบ 500
    text = _SURR.sub("\ufffd", text)
    # ตัวอักษรตกแต่งที่ทำให้ตรวจไม่เจอ: ช่องว่างล่องหน ("k\u200bill my\u200bself" "อ\u200bยากตาย"),
    # ตัวเต็มความกว้าง ("ｉ ｗａｎｔ ｔｏ ｄｉｅ") และขีดฆ่า/ตกแต่งแบบ combining ("d̷i̷e̷")
    text = _INVIS.sub("", text).translate(_FULLWIDTH)
    text = _DECOR.sub("", text)
    # ตัวอักษรเดียวซ้ำยาวๆ ("กกกก…" หลายพันตัว) ทำให้ตรวจช้า 1–2 วินาทีต่อข้อความ — ย่อเหลือ 12 ตัว
    # (ยังพอให้ "55555" "ๆๆ" "!!!!" อ่านความหมายได้เหมือนเดิม)
    text = _RUN.sub(lambda m: m.group(1) * 12, text) if len(text) > 200 else text
    return text if len(text) <= _MAX_LEN else text[:6000] + "\n" + text[-2000:]


# เขียนนิยาย/ทำรายงาน/เป็นอาสาสายด่วน — คำว่า "ฆ่าตัวตาย" อยู่ในงาน ไม่ได้อยู่ในใจคนพิมพ์
# ลดลงเฉพาะเมื่อไม่มีคำแทนตัวเองเลย ("ตัวละครอยากตาย เหมือนฉันตอนนี้" ยังเป็นวิกฤต)
_WORK_FRAME = re.compile(r"电影|電影|小说|小說|论文|論文|映画|小説|論文|レポート|영화|소설|논문|보고서|นิยาย|ตัวละคร|บทละคร|เขียนบท|รายงานเรื่อง|ทำรายงาน|งานวิจัย|วิทยานิพนธ์|สถิติ|ศึกษาเรื่อง|"
                         r"ฉาก\S{0,6}(?:ฆ่า|ยิง|ตาย)|หนังเรื่อง|ซีรีส์เรื่อง|ภาพยนตร์|ทางแฟชั่น|"
                         r"ป้องกันการฆ่าตัวตาย|อาสาสมัคร|\b(?:research|paper|essay|thesis|statistics|novel|"
                         r"character|screenplay|suicide prevention|overdose prevention|volunteer|movie|film|scene|tv show|series|documentary)\b", re.I)
_SELF_REF = re.compile(r"ฉัน|หนู|(?<!ตัด)(?<!สระ)(?<!ย้อม)(?<!ทรง)(?<!เส้น)(?<!ทำ)(?<!หวี)ผม|เรา|กู|ตัวเอง|เค้า|เขาว่า|อยากตาย|ไม่ไหว|"
                       r"\b(?:i'm|im|i(?!')|me|my|myself|mine)\b(?!\s+(?:volunteer|am (?:writing|researching)|writing|researching|write|study|studying|research|work))", re.I)


# "ฝันว่าจมน้ำ/รถชน/ระเบิดลง" = เล่าความฝัน ไม่ใช่เหตุตอนนี้ — แต่ความคิดอยากตายยังนับเสมอ
# และถ้าตื่นมาแล้วมีอาการจริง ("ฝันร้ายแล้วตื่นมาเจ็บหน้าอก") ไม่ลด
_DREAM = re.compile(r"^\s*(?:เมื่อคืน|คืนก่อน|เมื่อวาน)?\s*(?:ฉัน|หนู|ผม|เรา)?\s*ฝัน(?:ว่า|เห็น)|^\s*(?:last night )?i (?:dreamt|dreamed|had a dream)\b", re.I)
_WOKE_REAL = re.compile(r"ตื่น(?:มา|ขึ้นมา)|ตอนนี้|\b(?:woke up|now|right now)\b", re.I)


def _crisis_outside_frame(text: str, pattern=None) -> bool:
    """ตัดเฉพาะท่อนที่พูดถึงหนัง/งานเขียนออก แล้วดูว่าที่เหลือยังเป็นวิกฤตไหม
    ("ดูหนังเรื่องสึนามิ อยากหลับไม่ตื่น" เคยถูกมองว่าเป็นเรื่องในหนังทั้งข้อความ — ทดสอบหนัก 1 ล้านครั้งเจอ 28 แบบ)"""
    rest = text
    for m in reversed(list(_WORK_FRAME.finditer(text))):
        if re.search(r"[\u0E00-\u0E7F]", m.group()):        # ไทย: ท่อนคั่นด้วยช่องว่าง
            lo = text.rfind(" ", 0, m.start()) + 1
            hi = text.find(" ", m.end())
        else:                                               # ภาษาอื่น: ท่อนคั่นด้วยจุด/ขึ้นบรรทัด
            lo = max(text.rfind(c, 0, m.start()) for c in ".!?\n。") + 1
            hi = min([i for i in (text.find(c, m.end()) for c in ".!?\n。") if i >= 0] or [-1])
        hi = len(text) if hi < 0 else hi
        rest = rest[:lo] + " " + rest[hi:]
    rest = rest.strip()
    return bool(rest) and rest != text.strip() and _assess_raw(rest, pattern)["crisis"]


_THREAT_BY_OTHER = re.compile(
    r"\b(?:he|she|they|husband|boyfriend|bf|wife|girlfriend|gf|partner|dad|father|stepdad|stepfather|mom|mother|uncle|brother|sister|ex|boss|"
    r"someone|somebody|man|guy|woman|neighbou?r|landlord)\b[^\n]{0,24}?\bthreaten(?:s|ed|ing)? to\b", re.I)


_FICT_MARK = re.compile(r"นิยาย|เรื่องที่(?:ฉัน|ผม|เรา|หนู)?(?:เขียน|แต่ง)|ซีรีส์|การ์ตูน|มังงะ|อนิเมะ|เกม|ละคร|หนัง(?!สือ)|แฟนตาซี|ไซไฟ|"
                        r"(?i:\b(?:novel|story|stories|game|series|manga|anime|fanfic|fantasy|sci-?fi|screenplay|script|book)\b)")
_FICT_SELF = re.compile(r"เหมือน(?:ฉัน|ผม|หนู|เรา|กู|ตัวเอง|เค้า)|(?:ฉัน|ผม|หนู|เรา|กู)ก็|(?i:\blike me\b|\bsame as me\b|\bi feel (?:the same|like (?:him|her|them))|\bme too\b)")
_FICT_CHAR = re.compile(r"(?:ตัวละคร|พระเอก|นางเอก|ตัวเอก|ตัวร้าย|ตัวประกอบ)[^\s.!?,]*|"
                        r"(?i:\b(?:my|the|a|this|our|his|her)\s+(?:main\s+)?(?:character|protagonist|hero|heroine|villain|npc)\b[^.!?,\n]*)")


def assess(text: str, pattern: dict | None = None) -> dict:
    from core.thai_signals import canon_text
    text = canon_text(text)                     # เว้นวรรคซ้อน · ลากตัวอักษร — ทุกชั้นเห็นรูปเดียวกัน
    a = _assess_raw(text, pattern)
    if not a["crisis"] and a["text_risk"] >= 35 and isinstance(text, str) and _DREAM.search(text) \
            and not _WOKE_REAL.search(text):
        return dict(a, text_risk=0, risk=min(a["risk"], 20), risk_shown=0, disaster=None,
                    topics=[t for t in a["topics"] if t in ("positive", "soft_check")])
    # ไม่ปิดเงียบ — ยังถามไถ่เบาๆ พร้อมเบอร์ 1323 เหมือนกรณี "ขอข้อมูลไปทำรายงาน" ที่มีอยู่แล้ว
    if a["crisis"] and isinstance(text, str) and _WORK_FRAME.search(text) and not _SELF_REF.search(text) \
            and not _crisis_outside_frame(text, pattern):
        a = dict(a, crisis=False, topics=a["topics"] + ["soft_check"], text_risk=45,
                 risk=min(a["risk"], 45), risk_shown=min(a["risk_shown"], 45))
    elif isinstance(text, str) and _WORK_FRAME.search(text) and not _SELF_REF.search(text) \
            and any(t in ("trafficking", "violence", "sexual_abuse", "overdose") for t in a["topics"]):
        # "ศึกษาเรื่องการค้ามนุษย์ทำรายงาน" เคยได้ Risk 80 ราวกับกำลังถูกค้ามนุษย์
        a = dict(a, topics=[t for t in a["topics"] if t not in ("trafficking", "violence", "sexual_abuse", "overdose")],
                 text_risk=min(a["text_risk"], 20), risk=min(a["risk"], 20), risk_shown=min(a["risk_shown"], 20))
    from core.second_layer import apply as _second_layer
    a = _second_layer(text, a)
    # ชั้นสองอาจเติม harm_others กลับมา — คนที่ถูกคนอื่นขู่ไม่ใช่คนที่อยากทำร้ายใคร (ดู _THREAT_BY_OTHER)
    if isinstance(text, str) and "harm_others" in a["topics"] and "violence" in a["topics"] and _THREAT_BY_OTHER.search(text):
        a = dict(a, topics=[x for x in a["topics"] if x != "harm_others"])
    return _specific_first(text, _mother_baby_first(text, _with_conditions(text, a)))


def _specific_first(text, a: dict) -> dict:
    """ลำดับสุดท้ายของหัวข้อ — ทำหลังทุกชั้น เพราะชั้นก่อนหน้าอาจแทรก overdose/health_emergency กลับมาไว้หน้า
    1) คนไม่หายใจมาก่อนทุกเรื่อง (ยกเว้นวิกฤตที่มีคำตอบ 1669/CPR ของตัวเองอยู่แล้ว)
    2) หัวข้อเฉพาะมาก่อนหัวข้อกว้างที่ตอบผิดเรื่อง (_SPECIFIC_FIRST)"""
    topics = list(a.get("topics") or [])
    if not topics:
        return a
    calm = None
    for first, over in _SPECIFIC_FIRST:
        if first in topics and set(topics) & over:
            topics = [first] + [x for x in topics if x != first and not (x in over and x in _WRONG_FRAME)]
            calm = first if first in _CALIBRATED else calm
    if _NOT_BREATHING.search(str(text or "")) and not a.get("crisis") and topics[0] != "health_emergency":
        topics, calm = ["health_emergency"] + [x for x in topics if x != "health_emergency"], None
    if topics == a["topics"] and not calm:
        return a
    out = dict(a, topics=topics)
    # คำตอบบอก "ส่วนใหญ่ไม่อันตราย" แต่หัวคำตอบยังขึ้น 85/100 จากหัวข้อยาเกินขนาดที่ถูกแทน — ให้คะแนนตามหัวข้อที่ตอบจริง
    if calm and topics[0] == calm and not a.get("crisis") and not _DANGER_SIGNS.search(str(text or "")):
        r = _KP.RISK[calm]
        out.update(text_risk=r, risk=min(a.get("risk", r), max(r, 0)), risk_shown=min(a.get("risk_shown", r), r))
    return out


_UNCONSCIOUS = re.compile(r"หมดสติ|ไม่ตอบสนอง|\b(?:unconscious|unresponsive)\b", re.I)


def _mother_baby_first(text, a: dict) -> dict:
    """หลังคลอด/ทารก: ขั้นตอนเฉพาะ (ตกเลือดหลังคลอด ไข้ทารก) มาก่อนคำตอบฉุกเฉินทั่วไป
    เดิม "คลอดได้ 5 วัน เลือดชุ่มผ้าอนามัย" ได้แค่ "นั่งในท่าที่หายใจสบาย" — ยกเว้นหมดสติ ที่ต้องได้ CPR ก่อน"""
    tp = list(a.get("topics") or [])
    if not tp or tp[0] not in ("health_emergency", "first_aid", "health") or _UNCONSCIOUS.search(str(text or "")):
        return a
    for t_mn in ("newborn_danger", "post_danger", "post_harm") + _KP.URGENT:
        if t_mn in tp:
            tp.insert(0, tp.pop(tp.index(t_mn)))
            return dict(a, topics=tp)
    return a


# ตัวตรวจแบบเงื่อนไข (core/conditions.py) — ใคร × ทำอะไร × กับอะไร แทนรายการวลี · ผสานเข้าผลหลักที่นี่จุดเดียว
# หัวข้อด่วน (กลืนของอันตราย · สัญญาณเตือน · มิจฉาชีพ) ขึ้นหน้า เพื่อให้คำตอบหลักเป็นเรื่องนั้น · ไม่แตะเมื่อเป็นวิกฤตอยู่แล้ว
_COND_FIRST = ("swallowed", "overdose", "warning", "someone", "online_grooming", "sexual_abuse", "scam")
_COND_AHEAD = ("basic", "housing")


def _with_conditions(text, a: dict) -> dict:
    from core.conditions import check
    hits = check(text) if isinstance(text, str) and not a.get("crisis") else []
    if not hits:
        return a
    topics, scam, risk = list(a["topics"]), list(a.get("scam") or []), 0
    urgent_have = set(topics) & {"overdose", "swallowed", "household", "health_emergency", "pet_poison"}
    for h in hits:
        if h.topic in ("overdose", "swallowed") and urgent_have:      # ของเดิมจับเรื่องด่วนได้แล้ว คำตอบเฉพาะทางของเดิมดีกว่า
            risk = max(risk, h.risk)
            continue
        if h.topic in _COND_FIRST:
            topics = [h.topic] + [x for x in topics if x != h.topic]
        elif h.topic in _COND_AHEAD:                 # ปัจจัยพื้นฐาน: ขึ้นนำหัวข้อทั่วไป แต่ตามหลังเรื่องด่วนที่มีอยู่ (ความรุนแรง ฉุกเฉิน)
            rest = [x for x in topics if x != h.topic]
            k = next((i for i, x in enumerate(rest) if x not in _URGENT_TOPICS), len(rest))
            topics = rest[:k] + [h.topic] + rest[k:]
        elif h.topic and h.topic not in topics:
            topics = topics + [h.topic]
        if h.scam and h.scam not in scam:
            scam.append(h.scam)
        risk = max(risk, h.risk)
    return dict(a, topics=topics, scam=scam, conditions=[h.rule for h in hits], text_risk=max(a["text_risk"], risk),
                risk=max(a["risk"], risk), risk_shown=max(a["risk_shown"], risk) if isinstance(a.get("risk_shown"), (int, float)) else a.get("risk_shown"))


# ได้ยินเสียงคนถูกทำร้ายหรือร้องขอความช่วยเหลือจากห้อง/บ้านข้างๆ — ผู้ใช้เป็นพยาน ต้องได้ขั้นตอนโทร 191
_WITNESS_SOUND = re.compile(r"(?:ห้องข้างๆ|ห้องข้าง|ห้องบน|ห้องล่าง|บ้านข้างๆ|ข้างบ้าน|ห้องตรงข้าม|บ้านตรงข้าม)[^\n]{0,30}?"
                            r"(?:กรีดร้อง|ร้องให้ช่วย|ร้องขอความช่วยเหลือ|ช่วยด้วย|เสียงทุบตี|เสียงตบ|เสียงตี(?!ความ)|ร้องโหยหวน|ร้องไห้จ้า)")

_EN_FAMILY_HARM = re.compile(r"\bmy (?:dad|father|step-?dad|mom|mum|mother|step-?mom|husband|brother|uncle|grandpa|boyfriend)\b[^\n]{0,50}?"
                             r"\b(?:hit|hits|hitting|beat|beats|beating|punch\w*|kick(?:s|ed)?|slap\w*|chok\w*|strangl\w*|hurt(?:s|ing)?)\b[^\n]{0,10}?"
                             r"\b(?:my|our) (?:mom|mum|mother|dad|father|sister|brother|siblings|little \w+|kids?|children|grandma|grandpa)\b", re.I)
EN_FAMILY_HARM = ("What's happening at home is violence, not a family argument — everyone's safety comes first, including yours.\n\n{status}\n\n"
                  "1) If it's happening now, call the police (191 in Thailand, 911 in the US, 112 in most of Europe) and give the address clearly. "
                  "Don't step between them — go to a locked room or a neighbour's.\n"
                  "2) If anyone is hurt, get medical care and ask for the injuries to be recorded — it matters later.\n"
                  "3) The person being hurt can get a safe place and advice: in Thailand call 1300 (24 hours); elsewhere find local help at findahelpline.com\n\n"
                  "Is anyone hurt right now, and are you somewhere safe?\n\n{sign}")
_EN_THREAT = re.compile(r"\b(?:threaten\w*|said (?:he|she|they)(?:'?ll| will| would)|says? (?:he|she|they)(?:'?ll| will))\b[^\n]{0,10}?"
                        r"\b(?:to )?(?:hurt|kill|break|beat|stab|shoot|come (?:after|for)|find)\b", re.I)
EN_THREAT = ("Being threatened makes you unsafe even before anything happens — that fear is reasonable.\n\n{status}\n\n"
             "1) If you're in immediate danger, call the police now (191 in Thailand, or your local emergency number).\n"
             "2) Save every threat — messages, voice notes, call logs with times — and report it. Threats to hurt someone are a crime, "
             "including from lenders or collectors.\n"
             "3) Don't meet them alone. Tell someone you trust where you are, and vary your routine for now.\n\n"
             "Do they know where you live or work?\n\n{sign}")

_STRESS_TAIL = re.compile(r"[\s,]*(?:เครียด(?:มาก|จัง|สุดๆ|มากๆ)?|ไม่ไหวแล้ว|ไม่รู้จะทำไง)[\s!.~]*$")

def _assess_raw(text: str, pattern: dict | None = None) -> dict:
    """ประเมินข้อความ — ถ้าพิมพ์โดยไม่ใส่วรรณยุกต์ ("ลูกไมหายใจ") ลองฉบับที่เติมวรรณยุกต์ด้วย แล้วใช้ฉบับที่เห็นอันตรายมากกว่า"""
    text = _clip(text)
    a = _assess(text, pattern)
    plain = normalize_mixed(text)
    loc = dedialect(plain)
    if loc != plain:                            # ภาษาถิ่น: ใช้ฉบับคำกลางเมื่อเห็นอันตรายมากกว่า
        d = _assess(loc, pattern)
        if d["text_risk"] > a["text_risk"]:
            a, plain = d, loc
    alt = retone(plain)
    if alt != plain:
        b = _assess(alt, pattern)
        # ฉบับเติมวรรณยุกต์ใกล้กับที่ผู้ใช้ตั้งใจพิมพ์กว่า ("อานขาว…" = "อ่านข่าว…" ไม่ใช่เรื่องด่วน)
        # ยกเว้นฉบับเดิมเห็นวิกฤตแต่ฉบับเติมไม่เห็น — ไม่ยอมเสียสัญญาณวิกฤตเพราะเติมผิดคำ
        if _TONE_RE_KV.search(plain):           # พิมพ์ใส่วรรณยุกต์บางคำ: ใช้ฉบับที่เห็นอันตรายมากกว่า (ฉบับเติมเป็นแค่ทางเลือก)
            return b if (b["crisis"] and not a["crisis"]) or b["text_risk"] > a["text_risk"] else a
        return a if (a["crisis"] and not b["crisis"]) else b
    return a


_TONE_RE_KV = re.compile("[\u0e48\u0e49\u0e4a\u0e4b]")


def _assess(text: str, pattern: dict | None = None) -> dict:
    """ตัวเลขของระบบ (ไม่มี LLM): W, Risk, หัวข้อ, ความเร่งด่วน"""
    text = normalize_mixed(text)                # "I want to dieค่ะ" — เว้นวรรคอังกฤษ/ไทยที่พิมพ์ติดกัน
    t = text.lower()
    p = pattern if isinstance(pattern, dict) else {}
    E = max(0.0, min(100.0, _num(p.get("entropy"), 40)))
    R = max(0.0, min(100.0, _num(p.get("resource"), 50)))
    S = max(0.0, min(100.0, _num(p.get("stability"), 60)))
    W = ((100 - E) + R + S) / 3
    risk = 0.5 * E + 0.5 * (100 - R)

    tr = {}
    try:
        from ENGINE.risk_engine import evaluate_risk
        tr = evaluate_risk(text) or {}
    except Exception:
        pass
    # "เพื่อนบอกว่าอยากตาย" → ผู้ใช้กำลังช่วยคนอื่น: วิกฤตของผู้ใช้ดูจากส่วนที่เหลือของข้อความ
    own = strip_third_party(t) if (THIRD_PARTY_CRISIS.search(t) or tr.get("third_party")) else t
    soft = bool(SOFT_CRISIS.search(own))
    own = strip_soft_crisis(own)
    # ตัวละครในนิยาย/เกม/ซีรีส์ ("ตัวละครในนิยายแฟนตาซีอยากตาย" "my character wants to die in the novel") ไม่ใช่วิกฤตของผู้ใช้
    # ตัดเฉพาะท่อนของตัวละคร — "ตัวละครอยากตาย เหมือนฉันเลย อยากตายเหมือนกัน" ส่วนของผู้ใช้ยังถูกจับ
    # ไม่ตัดทิ้งเฉยๆ: เรื่องแต่งที่มีการตายลดจากวิกฤตเป็นการถามไถ่เบาๆ (คนเขียนเรื่องหนักก็ควรได้คำถามว่าตัวเองโอเคไหม)
    # และ "เหมือนฉัน" "ฉันก็" = ผู้ใช้เทียบกับตัวเอง → วิกฤตเหมือนเดิม
    fiction = bool(_FICT_MARK.search(t) and _FICT_CHAR.search(own) and not _FICT_SELF.search(t))
    fiction_hit = False
    if fiction:
        fiction_hit = bool(tr.get("self_harm")) or _hit(own, CRISIS_PHRASES)
        own = _FICT_CHAR.sub(" ", own)
    crisis = (bool(tr.get("self_harm")) and not fiction) or _hit(own, CRISIS_PHRASES)
    if fiction_hit and not crisis:
        soft = True
    # "พี่เคยทำร้ายเขา … ตอนนี้ไม่มีแล้ว" — ผู้ใช้สารภาพเรื่องเก่า ไม่ใช่คนที่กำลังถูกทำร้าย
    t_now, own = strip_own_past_harm(t), strip_own_past_harm(own)
    topics = [name for name, phrases, _ in TOPICS if _hit(own if name in _OWN_ONLY else t_now, phrases)]
    # "ปวดหลังเรื้อรังมาหลายเดือน เครียดมาก" — คำว่าเครียดท้ายประโยคบอกความรู้สึก ไม่ใช่ตัวปัญหา
    # เดิมหัวข้อ stress มาก่อนเรื่องจริง คำตอบจึงเปลี่ยนเป็น "ตอนนี้ไม่ต้องแก้ทุกอย่าง" (10 เรื่องในคลัง 394 ข้อ)
    if "stress" in topics and len(topics) > 1 and not _hit(_STRESS_TAIL.sub("", t_now), next(ph for nm, ph, _ in TOPICS if nm == "stress")):
        topics = [n for n in topics if n != "stress"] + ["stress"]
    # คนอื่นขู่จะทำร้ายผู้ใช้หรือลูก ("my ex threatened to hurt my kids") = ผู้ใช้เป็นฝ่ายถูกขู่ ไม่ใช่คนที่อยากทำร้ายใคร
    # เดิมถูกจับเป็น harm_others แล้วตอบว่า "ความโกรธขนาดนี้…" กับคนที่กำลังกลัว
    if "harm_others" in topics and "violence" in topics and _THREAT_BY_OTHER.search(t_now):
        topics = [n for n in topics if n != "harm_others"]
    # สัตว์เลี้ยงกินของมีพิษ: ยาเกินขนาด/ปฐมพยาบาล/สุขภาพ ต้องเป็นเรื่องของคนในส่วนที่เหลือของข้อความ
    if "pet_poison" in topics:
        human = strip_pet_poison(t_now)
        topics = [n for n in topics if n not in ("overdose", "first_aid", "health")
                  or _hit(human, next(ph for nm, ph, _ in TOPICS if nm == n))]
    # รอบด้านกลับ: "หนังเรื่องนี้ฉากคนจมน้ำน่ากลัว" "อ่านข่าวคนถูกแทง" เคยได้ Risk 85 · "ตกบันไดนิดเดียวไม่เป็นไร"
    # "แมวกัดเล่นไม่เข้าเนื้อ" เคยได้ 75 — เรื่องในหนัง/ข่าวที่ไม่เกี่ยวกับคนใกล้ตัว และเจ็บเล็กน้อยที่ผู้ใช้บอกเองว่าไม่เป็นไร
    if _FICTION.search(t_now) and not _CLOSE.search(t_now):
        topics = [n for n in topics if n not in ("health_emergency", "first_aid")]
    if "first_aid" in topics and _MINOR.search(t_now) and not _RED_FLAG.search(t_now):
        topics = [n for n in topics if n != "first_aid"]
    if soft and not crisis and not set(topics) & set(_URGENT_TOPICS):
        topics.insert(0, "soft_check")         # ไม่ใช่วิกฤต แต่เป็นห่วงเบาๆ และบอกว่าโทรได้ถ้าวันไหนไม่ไหว
    if tr.get("third_party") and "someone" not in topics:      # "เพื่อนบอกว่ากรีดแขน" — คนอื่นกำลังวิกฤต
        topics.insert(0, "someone")
    # ภาษาอื่น (zh ja ko es): เรื่องด่วนเข้าหัวข้อเดียวกับภาษาไทย — "เพื่อนอยากตาย" ไม่ใช่วิกฤตของผู้ใช้เอง
    intl = urgent_intl(text, "all") if detect_lang(text) != "en" else []
    for kind_i, topic_i in intl:
        if kind_i == "someone":               # คนอื่นอยากตาย — ผู้ใช้วิกฤตเองเฉพาะเมื่อพูดถึงตัวเองด้วย
            from core.lang_signals import strip_someone_intl
            crisis = bool(tr.get("self_harm")) or _hit(strip_someone_intl(own), CRISIS_PHRASES)
        if topic_i not in ("disaster", "scam") and topic_i not in topics:
            topics.append(topic_i)
    # ภาษาอื่นนอกหกภาษาหลัก (เวียดนาม พม่า เขมร ลาว อาหรับ ฯลฯ) — เดิมได้ Risk 0 ทั้งหมด
    for kind_w in world_urgent(text):
        if kind_w == "crisis":
            crisis = True
        else:
            topic_w = {"medical": "health_emergency", "violence": "violence", "help": "help",
                       "danger": "help", "scam": "help"}[kind_w]
            if topic_w not in topics:
                topics.append(topic_w)
    # อารมณ์หนัก/ภัยที่พูดสั้น ในภาษา ja zh ko es vi (core/mood_intl) — เดิมได้ Risk 0 และแผนสามขั้นทั่วไป
    from core.mood_intl import mood_intl
    mood = mood_intl(text)
    if mood:
        kind_m = mood[0]
        if kind_m == "crisis":
            crisis = True
        else:
            topic_m = {"danger": "violence", "anger_kill": "harm_others"}.get(kind_m, "soft_check")
            if topic_m not in topics:
                topics.insert(0, topic_m)
    if tr.get("basic_needs") and "basic" not in topics:
        topics.insert(0, "basic")
    elif "basic" in topics:                    # ขาดปัจจัยพื้นฐาน มาก่อนเรื่องเงินทั่วไป
        topics.insert(0, topics.pop(topics.index("basic")))
    text_risk = {"critical": 90, "high": 75, "medium": 55}.get(str(tr.get("level")), 0)
    if fiction_hit and not crisis:            # ระดับนี้มาจากคำว่า "ตาย" ของตัวละคร ไม่ใช่ของผู้ใช้ — เหลือแค่การถามไถ่เบาๆ (45)
        text_risk = 0
    if crisis:
        text_risk = max(text_risk, 95)
    if any(x in topics for x in ("violence", "health_emergency", "overdose", "sexual_abuse", "someone")):
        text_risk = max(text_risk, 90 if "someone" in topics else 85)
    # อาการขาดสุรา (ชักได้) · ไข้เลือดออกที่เกล็ดเลือดต่ำ/มีอาการเตือน — เดิม Risk 0 จึงไม่ได้ตอบฟรีตอนโควตาหมด
    if _WITHDRAWAL.search(t):
        text_risk = max(text_risk, 75)
    if _DENGUE_WARN.search(t):
        text_risk = max(text_risk, 75)
    for name, lvl in _TOPIC_RISK.items():
        if name in topics:
            text_risk = max(text_risk, lvl)
    # ตั้งครรภ์อายุต่ำกว่า 15 — ต้องมีผู้ใหญ่ช่วยและอาจเป็นการถูกล่วงละเมิด (รอบหาบั๊ก 6)
    if "pregnancy" in topics and re.search(r"อายุ\s*(?:1[0-4]|[89])(?!\d)|(?<!\d)(?:1[0-4]|[89])\s*(?:ขวบ|ปี)(?!\d)|\b(?:1[0-4]|[89]) ?(?:yo|years? old)\b", t):
        text_risk = max(text_risk, 65)
    # ปืนในบ้าน: เล่าเฉยๆ ไม่ตื่นตูม (50) — แต่ไม่รู้ของใคร/กลัว/ขู่/เมา หรือมีความคิดทำร้าย = อันตรายจริง (85)
    if "weapon" in topics:
        danger = WEAPON_DANGER.search(t) or text_risk >= 65 or set(topics) & {"harm_others", "violence", "warning"}
        text_risk = max(text_risk, 85 if danger else 50)
    if GAMBLING_LOSS.search(t):                # พนันจนหมดตัว/เป็นหนี้ — มักลามเป็นหนี้นอกระบบและความคิดทำร้ายตัวเอง
        text_risk = max(text_risk, 60)
        if "addiction" not in topics:
            topics.append("addiction")
    if DEBT_HARASS.search(t):                  # ทวงหนี้ขู่/ประจาน — ผิดกฎหมายและกดดันหนัก
        text_risk = max(text_risk, _DEBT_HARASS_RISK)
    # หัวข้อเฉพาะที่ต้องมาก่อนหัวข้อกว้าง — คำตอบกว้างตอบผิดเรื่อง
    # "แม่ใกล้เสียแล้ว" (ยังไม่เสีย) เคยได้ "เสียใจด้วย การสูญเสีย…" · ลูกออทิสติกอาละวาดเคยได้ "ถามตรงๆ ว่าคิดจะทำร้ายตัวเองไหม"
    for _first, _over in _SPECIFIC_FIRST:
        if _first in topics and set(topics) & _over:
            topics = [_first] + [x for x in topics if x != _first and not (x in _over and x in _WRONG_FRAME)]
    # มิจฉาชีพ (แอบอ้าง/ลิงก์/โอนเงิน) — เลือกจากโครงสร้าง ไม่ใช่คำเดี่ยว
    scam = scam_flags(text)
    if scam:
        topics = ["scam"] + [x for x in topics if x != "scam"]
        # "ถูกหลอกมาทำงาน บังคับไม่ให้ออก" — คำว่า "ถูกหลอก" ทำให้ได้ขั้นตอนขอเงินคืน ทั้งที่เป็นการบังคับใช้แรงงาน
        if "trafficking" in topics and set(scam) <= {"lost"}:
            topics = ["trafficking"] + [x for x in topics if x != "trafficking" and x != "scam"]
            scam = []
        # "ถูกหลอกเปิดบัญชีม้า" — คนพิมพ์คือคนที่อาจถูกดำเนินคดี ไม่ใช่คนที่โอนเงินไป ขั้นตอนขอเงินคืนช่วยเขาไม่ได้
        elif "kp_money_mule" in topics and set(scam) <= {"lost", "job"}:
            topics = ["kp_money_mule"] + [x for x in topics if x not in ("kp_money_mule", "scam")]
            scam = []
        text_risk = max(text_risk, 75 if set(scam) & {"impersonation", "story", "job", "romance"} else 60)
    # กลโกงไซเบอร์ที่ผู้ใช้กำลังเจอ (core/cyber_scam) — SMS ใบสั่ง · .apk · สิทธิ์ช่วยเหลือการเข้าถึง · คนมารับเงินที่บ้าน ฯลฯ
    from core.cyber_scam import cyber_kind
    cyber = cyber_kind(text) if not crisis else None
    if cyber:
        text_risk = max(text_risk, cyber[1])
        if "scam" not in topics:
            topics.insert(0, "scam")
    if "warning" in topics and not crisis:
        text_risk = max(text_risk, 65)
    if "help" in topics:
        text_risk = max(text_risk, 50)
    # ผู้ใหญ่ชวนไปที่ลับตาแล้วขอให้เก็บเป็นความลับ — สัญญาณล่อลวงที่ชัดกว่าการชวนเฉยๆ
    if "adult_invite" in topics and re.search(r"(?:ห้าม|อย่า|ไม่ให้|ไม่ต้อง)บอก|เป็นความลับ|รางวัลพิเศษ|\bdon'?t tell\b|\bsecret\b", t):
        text_risk = max(text_risk, 65)
    if "basic" in topics:
        text_risk = max(text_risk, 75)
        W = min(W, 30)
    if crisis:
        W = min(W, 20)
    # โครงสร้างของข้อเสนอ (การันตี + เร่ง + ชวนผ่านคนรู้จัก) — แยกจากอารมณ์ผู้ใช้
    flags = offer_red_flags(text)
    text_risk = max(text_risk, offer_risk(flags))
    # ความรุนแรง/การควบคุมในความสัมพันธ์ (ENGINE/relationship_engine ผ่าน core/engine_bridge)
    rel = None
    try:
        from core.engine_bridge import _relationship
        rel = _relationship(strip_own_past_harm(text))
    except Exception:
        pass
    if rel:
        text_risk = max(text_risk, rel["data"]["risk_score"])
    # ภัยที่กำลังเจอ (DOMAINS/survival_engine ผ่าน core/engine_bridge) — เดิม "น้ำท่วมบ้าน" ได้ Risk 0
    dis = None
    try:
        from core.engine_bridge import _disaster
        dis = _disaster(text)
    except Exception:
        pass
    if dis and dis["data"]["active"]:
        text_risk = max(text_risk, dis["data"]["threat"])
        # "เป็นลมแดด ตัวร้อนจัด" เคยได้ Risk 59 — โรคลมแดดในตัวคนเป็นเรื่องฉุกเฉิน ไม่ใช่แค่สภาพอากาศ
        if dis["data"].get("kind") == "heat" and re.search(r"ไม่มีเหงื่อ|ตัวร้อนจัด|ซึม|สับสน|ชัก|หมดสติ|เป็นลมแดด|โรคลมแดด|ฮีทสโตรก|ฮีตสโตรก", text):
            text_risk = max(text_risk, 75)
    kinds_i = [kd for kd, _ in intl]
    if "disaster" in kinds_i or "scam" in kinds_i or "basic" in kinds_i:
        text_risk = max(text_risk, 70)
    return {
        "intl_urgent": kinds_i, "mood_intl": mood, "cyber": cyber[0] if cyber else None,
        "scam": scam,
        "W": round(W), "risk": round(max(risk, text_risk)),
        # ตัวเลขที่โชว์ในคำตอบ: ยังไม่รู้สถานะจริงของผู้ใช้ → W "—" และ Risk จากข้อความล้วน
        # (เดิมโชว์ "W 57 · Risk 45" จากค่าตั้งต้น ขณะที่แถบใต้คำตอบโชว์ "W — · Risk 0" — สองตัวเลขขัดกัน)
        "W_shown": round(W) if p else "—", "risk_shown": round(max(risk, text_risk)) if p else round(text_risk),
        # risk จากข้อความล้วน (0 = ไม่มีสัญญาณ) — ใช้ยกค่า risk_score ที่ engine คิดจากสถานะอย่างเดียว
        "text_risk": round(text_risk), "offer_flags": flags,
        "relationship": rel["data"]["status"] if rel else None,
        "disaster": dis["data"] if dis and dis["data"]["active"] else None,
        "crisis": crisis, "topics": topics, "money": _money(text),
        "options": _options(text or ""),
    }


# ── บรรทัดสถานะในคำตอบ: ภาษาคนแทนสูตร ──────────────────────────────
# เดิมคำตอบขึ้นต้นด้วย "W — · Risk 55 · Choice(t) = 3" ซึ่งคนทั่วไปอ่านไม่ออก (แผงขวาเปลี่ยนเป็นภาษาคนแล้ว)
# เกณฑ์เดียวกับ riskWord ใน static/index.html: เกิน 80 ต้องดูแลด่วน · เกิน 60 ควรระวัง
# ไม่บอกจำนวนทาง — รายการข้อด้านล่างบอกเองอยู่แล้ว · ภาษาที่ไม่มีคำแปลไม่ใส่บรรทัดนี้
_STATUS_WORDS = {
    "th": ("ความเสี่ยงตอนนี้", ("ยังรับมือได้", "ควรระวัง", "ต้องดูแลด่วน")),
    "en": ("Risk right now", ("manageable", "take care", "needs care now")),
    "zh": ("目前的风险", ("还能应对", "需要注意", "需要马上处理")),
    "ja": ("今のリスク", ("対応できる", "注意", "すぐに対応を")),
    "ko": ("지금 위험도", ("감당할 수 있어요", "조심해야 해요", "지금 바로 도움이 필요해요")),
    "es": ("Riesgo ahora", ("manejable", "con cuidado", "necesita atención ya")),
    "vi": ("Rủi ro lúc này", ("kiểm soát được", "cần cẩn thận", "cần chăm sóc ngay")),
}
_SHOWN_RISK = re.compile(r"\((\d+)/100\)")


def _compose_mood_intl(a: dict, mood, sign: str, footer: bool):
    """ภัย → คำตอบเรื่องความปลอดภัย · วิกฤต → สายด่วน · โกรธ/อารมณ์หนัก → รับฟังและถามไถ่ ในภาษาของผู้ใช้"""
    from core.mood_intl import MOOD_REPLY
    from core.lang_signals import URGENT_REPLY, ASK_LABEL, FOOTER, TH_NUMBERS
    kind, lg = mood
    st = status_line(a, lg)
    if a["crisis"] or kind in ("crisis", "danger"):
        k = "crisis" if a["crisis"] else "violence"
        if lg == "vi":
            from core.world_replies import compose_world
            return compose_world("vi", k, st, sign, footer)
        if k == "violence":
            return compose_urgent_intl(lg, "violence", st, sign, footer)
        return compose_intl(lg, True, st, sign, footer)
    opener, steps, ask = MOOD_REPLY[kind][lg]
    body = "\n".join(f"{i + 1}) {x}" for i, x in enumerate(steps))
    th = f"{TH_NUMBERS[lg]}\n\n" if lg in TH_NUMBERS and kind == "anger_kill" else ""
    tag = "\n" + FOOTER[lg] if footer else ""
    return f"{opener}\n\n{st}\n\n{th}{body}\n\n{ask}\n\n{sign}" + tag


def risk_phrase(a: dict, lang: str = "th") -> str:
    """"ควรระวัง (65/100)" — ตัวเลขเดียวกับ risk_score ที่แผงขวาใช้"""
    risk = round(a.get("risk_shown", a["risk"]))
    words = _STATUS_WORDS.get(lang, _STATUS_WORDS["en"])[1]
    return f"{words[2 if risk > 80 else 1 if risk > 60 else 0]} ({risk}/100)"


def status_line(a: dict, lang: str = "th") -> str:
    if lang not in _STATUS_WORDS:
        return ""
    return f"{_STATUS_WORDS[lang][0]}: {risk_phrase(a, lang)}"


_PHRASE = re.compile("(" + "|".join(re.escape(w) for _, ws in _STATUS_WORDS.values() for w in ws) + r") \(\d+/100\)")


def restate_risk(reply: str, risk: float) -> str:
    """เปลี่ยนตัวเลขความเสี่ยงในคำตอบ (ครั้งแรก) พร้อมคำที่ตรงกับตัวเลขใหม่ ในภาษาเดิมของคำตอบ"""
    def put(m):
        lang = next(lg for lg, (_, ws) in _STATUS_WORDS.items() if m.group(1) in ws)
        return risk_phrase({"risk": risk}, lang)
    return _PHRASE.sub(put, str(reply), count=1)


def shown_risk(reply: str) -> int | None:
    """ตัวเลขความเสี่ยงที่คำตอบบอกผู้ใช้ — ไม่มีคืน None"""
    m = _SHOWN_RISK.search(str(reply or ""))
    return int(m.group(1)) if m else None


def _compose(text: str, route: str = "general", voice_mode: str = "lyla",
            pattern: dict | None = None, footer: bool = True) -> str:
    """คำตอบเต็มจากสมการ — ไม่มี AI · input เดิม → คำตอบเดิม"""
    text = _clip(text)
    if voice_mode == "council":
        return compose_council(text, footer=footer)
    a = assess(text, pattern)
    vega = voice_mode == "vega" or route == "vega"
    if vega and detect_lang(text) == "th" and a["text_risk"] < 60 and not a["crisis"] and not a.get("scam") and not a["offer_flags"]:
        from core import decision_brief as _db
        if _db.applies(text):
            return _db.vega(text, footer=footer)     # VEGA: ด้านเสียจากตัวเลขจริง + ประตูเดินหน้า/หยุด
    end = "ครับ" if vega else "ค่ะ"
    sign = "— VEGA ◆" if vega else "— LYLA ◈"
    tag = "\n· ตอบจากสมการของระบบ — ไม่ได้ใช้ AI" if footer else ""
    t = text.lower()

    # ── ภาษาเอเชียที่มีคำตอบเรื่องด่วนของตัวเอง (พม่า เขมร ลาว เวียดนาม ฮินดี ฯลฯ) ──
    if world_urgent(text):
        from core.world_replies import world_lang, compose_world as compose_asia
        al = world_lang(text, 1)
        kind = ("crisis" if a["crisis"] else "medical" if "health_emergency" in a["topics"]
                else "violence" if "violence" in a["topics"] else "help" if "help" in a["topics"] else None)
        if not al and kind == "help":               # "救命" "助けて" "살려주세요" "ayuda" คำเดียว
            from core.world_replies import help_main
            hm = help_main(detect_lang(text))
            if hm:
                st = status_line(a, detect_lang(text))
                body = "\n".join(f"{i + 1}) {x}" for i, x in enumerate(hm[1]))
                return (f"{hm[0]}\n\n" + (f"{st}\n\n" if st else "") + f"{body}\n\n{hm[2]}\n\n{sign}"
                        + ("\n· Answered from the system's equations — no AI used" if footer else ""))
        if al and kind:
            st = status_line(a, al)
            out = compose_asia(al, kind, st, sign, footer)
            if out:
                return out

    # ── อารมณ์หนัก/ภัยที่พูดสั้นในภาษา ja zh ko es vi (core/mood_intl) ──
    if a.get("mood_intl"):
        out = _compose_mood_intl(a, a["mood_intl"], sign, footer)
        if out:
            return out

    # ── ภาษาอื่น: สมการเดียวกัน (W · Risk · Choice) แต่ใช้คำตอบของภาษานั้น ──
    lang = detect_lang(text)
    if lang != "th":
        status = status_line(a, lang)
        # มิจฉาชีพที่ตัวจับหลายภาษาเจอ (core/thai_signals) — เดิม "警察から電話で安全な口座に振り込め"
        # "Me llamó la policía… cuenta segura" ได้คำตอบทั่วไป และภาษาเวียดนามได้คำตอบภาษาอังกฤษ
        scam_lang = "vi" if script_lang(text) == "vi" else lang
        if a.get("scam") and not a["crisis"] and "recovery" not in a["scam"] and scam_lang in ("zh", "ja", "ko", "es", "vi"):
            return compose_urgent_intl(scam_lang, "scam", status_line(a, scam_lang), sign, footer)
        if lang == "en" and not a["crisis"] and not a["relationship"]:
            try:
                from core.creator_story import detect_creator_question, CREATOR_STORY_EN
                if detect_creator_question(text):
                    return CREATOR_STORY_EN.strip() + f"\n\n{sign}"
            except Exception:
                pass
        haz = EN_HAZARD.get((a.get("disaster") or {}).get("kind")) if (lang == "en" and not a["crisis"] and not _person_first(t, a)) else None
        if haz is EN_HAZARD["intruder"] and re.search(r"\bfollow(?:ing|ed)? me\b|\bbeing followed\b|\bstalking me\b", t, re.I) \
                and not re.search(r"\b(?:house|home|room|apartment|door|window)\b", t, re.I):
            haz = EN_FOLLOWED                            # ถูกตามข้างนอก ≠ ถูกบุกบ้าน (เดิมข้อแรกให้ล็อกตัวเองในห้อง)
        if haz:
            return ("Your safety comes first right now — things can be replaced.\n\n" + status + "\n\n"
                    + "\n".join(f"{i + 1}) {p}" for i, p in enumerate(haz))
                    + "\n\n" + _EN_LOCAL.format(th="191 police · 1669 medical · 199 fire · 1784 disaster")
                    + "\n\nWhere are you right now, and is anyone with you?\n\n" + sign
                    + ("\n· Answered from the system's equations — no AI used" if footer else ""))
        en_key = a["topics"][0] if a["topics"] else None
        if en_key == "health_emergency":
            en_key = ("en_drowning" if re.search(r"\bdrown", t, re.I)
                      else "en_cpr" if _NOT_BREATHING.search(t) or re.search(r"\bunconscious\b", t, re.I)
                      else "en_stroke" if re.search(r"\bstroke\b|\bcan'?t (?:speak|talk)|\bslurr|\bface (?:is )?droop|\bconfused\b|\blopsided\b|\bcrooked (?:face|smile)\b|\bjumbled\b|\bgarbled\b", t, re.I) else en_key)
        if en_key in ("health_emergency", "first_aid", "violence", "swallowed", "overdose"):
            for rx, k in _EN_FIRST_STEP:
                if rx.search(t) and (k != "en_swallowed_adult" or not re.search(r"\b(?:child|son|daughter|kid|baby|toddler)\b", t, re.I)):
                    en_key = k
                    break
        if en_key == "overdose" and "swallowed" in a["topics"]:
            en_key = "swallowed"    # "my child swallowed a battery" เคยได้ "some pills act slowly"
        if "recovery" in (a.get("scam") or []):
            en_key = "scam_recovery"
        elif not a["crisis"] and _magga_topic(t) and not (a.get("scam") or a.get("offer_flags")):
            en_key = "magga_" + _magga_topic(t)
        elif not a["crisis"] and CODE_REQ.search(t) and not (a.get("scam") or a.get("offer_flags")):
            en_key = "code_help"
        # ความรุนแรงในบ้านที่ผู้ใช้เห็น / การถูกขู่ทำร้าย — ภาษาไทยมีคำตอบ ภาษาอังกฤษเคยไม่มี
        # ("my dad drinks every night and beat my mom tonight" ได้วิธีเลิกเหล้าของผู้ใช้เอง ·
        #  "loan shark said he'll break my legs" ได้ "Let's lay this out step by step.")
        if lang == "en" and not a["crisis"] and not a["relationship"] and _EN_FAMILY_HARM.search(t) \
                and not re.search(r"\b(?:hit|hits|hitting|beat|beats|beating|hurt\w*|chok\w*|kick\w*|punch\w*)\b[^\n]{0,6}?\bme\b", t, re.I):
            return EN_FAMILY_HARM.format(status=status, sign=sign) + ("\n· Answered from the system's equations — no AI used" if footer else "")
        if lang == "en" and not a["crisis"] and not a["relationship"] and "violence" not in a["topics"] and _EN_THREAT.search(t):   # คู่ชีวิตขู่ → SAFETY_EN ที่ละเอียดกว่า
            return EN_THREAT.format(status=status, sign=sign) + ("\n· Answered from the system's equations — no AI used" if footer else "")
        lz = _lens.find(t, "en", "vega" if vega else "lyla") if (lang == "en" and not a["crisis"] and a["text_risk"] < 85
                                     and not a["relationship"]) else None
        if lz and not ((set(a["topics"]) & set(_URGENT_TOPICS)) <= set(lz.get("over") or ())
                       and (a["text_risk"] < 75 or lz.get("over"))):
            lz = None      # กติกาเดียวกับภาษาไทย: เรื่องด่วนรับแทนได้เฉพาะเลนส์ที่ประกาศ over
        if lz:
            lz = _person.adapt_main(lz, _person.read(t), "en")
        if lz:      # เลนส์ปัญหา (core/problem_lens.py) — เดิม "comparing myself on Instagram" ได้ "Let's lay this out step by step."
            return (lz["open"][0] + f"\n\n{status}\n\n" + "\n".join(f"{i + 1}) {p}" for i, p in enumerate(lz["paths"]))
                    + f"\n\n{lz['ask']}\n\n{sign}" + ("\n· Answered from the system's equations — no AI used" if footer else ""))
        en = EN_TOPIC.get(en_key) if (lang == "en" and (a["topics"] or str(en_key).startswith("magga_") or en_key == "code_help") and not a["crisis"]) else None
        if en:
            return (en[0] + f"\n\n{status}\n\n" + "\n".join(f"{i + 1}) {p}" for i, p in enumerate(en[1]))
                    + f"\n\n{en[2]}\n\n{sign}" + ("\n· Answered from the system's equations — no AI used" if footer else ""))
        if lang == "en" and not a["crisis"] and a["text_risk"] < 50 and CHANGE_OTHER.search(t) and not _HARM_OTHER.search(t) and not _TITAN_POWER.search(t) and not _TITAN_EXIT.search(t):
            return CHANGE_OTHER_EN + f"\n\n{sign}" + ("\n· Answered from the system's equations — no AI used" if footer else "")
        chat_en = small_talk(text) if (lang == "en" and not a["topics"] and not a["crisis"]) else None
        if chat_en:
            say = {"thanks": "You're welcome! Write any time you want to think something through.",
                   "night": "Good night — rest well. We can pick this up tomorrow.",
                   "laugh": "Glad to hear you laugh Anything you want to talk about?",
                   "who": (f"I'm {'VEGA' if vega else 'LYLA'}, KING DIADEM's assistant — an AI, not a person. I help you think "
                           "through what's weighing on you and lay out options you can still step back from. "
                           "I'm not a doctor or a lawyer; for urgent things I'll point you to real help."),
                   "bored": "A quiet moment can be useful. Is there something you'd like to do or think through?"}[chat_en]
            return f"{say}\n\n{sign}" + ("\n· Answered from the system's equations — no AI used" if footer else "")
        if lang == "en" and not a["topics"] and not a["crisis"] and len(t.strip()) <= 24 and _hit(t, GREETINGS):
            return (f"Hi! Tell me what you're deciding, or what's weighing on you — I'll help lay out the options.\n\n{sign}"
                    + ("\n· Answered from the system's equations — no AI used" if footer else ""))
        if lang == "en" and not a["crisis"] and a["relationship"] in ("collapse_risk", "critical"):
            return SAFETY_EN.format(status=status, sign=sign) + ("\n· Answered from the system's equations — no AI used" if footer else "")
        if lang in ("zh", "ja", "ko", "es") and a.get("intl_urgent") and not a["crisis"]:
            return compose_urgent_intl(lang, a["intl_urgent"][0], status, sign, footer)
        d = debt_en(text) if (lang == "en" and not a["crisis"] and not a["topics"]) else None
        if d:
            # ทางเลือกไม่เกิน 3 ข้อตาม canon — ยอดหนี้ · ผลของค่างวด · ขั้นถัดไป ส่วนหมายเหตุ (ดอกที่สมมติ/ดอกโหด) ไม่นับเป็นทาง
            steps = [d["lines"][0], d["lines"][-1],
                     "Call the lender before you miss a payment and ask about a hardship plan or a lower rate — "
                     "you have more options before you fall behind."]
            notes = "".join(f"\n· {n}" for n in d["lines"][1:-1])
            return ("Debt is just numbers — it can be handled one piece at a time.\n\n" + status + "\n\n"
                    + "\n".join(f"{i + 1}) {p}" for i, p in enumerate(steps)) + notes
                    + "\n\nIf you could only pay one bill this month, which one would hurt most to miss?\n\n" + sign
                    + ("\n· Answered from the system's equations — no AI used" if footer else ""))
        b = budget_en(text) if (lang == "en" and not a["crisis"] and not a["topics"]) else None
        if b:
            steps = ([b["line"],
                      "List the next 30 days of costs as must-pay · can-delay · can-cut — cut from the last pile first.",
                      "Look for one extra income source using skills you already have, before any long-term plan."]
                     if b["left"] <= 0 else
                     [b["line"],
                      "Pay yourself first: move a fixed amount to a separate savings account the day you're paid.",
                      "Build an emergency fund of 3–6 months of essential costs before investing or taking on new debt."])
            return ("Here are your own numbers first.\n\n" + status + "\n\n" + "\n".join(f"{i + 1}) {p}" for i, p in enumerate(steps))
                    + "\n\nIf something unexpected happened tomorrow, how many months would your savings cover?\n\n" + sign
                    + ("\n· Answered from the system's equations — no AI used" if footer else ""))
        # เรื่องทั่วไปในภาษาเอเชีย ยุโรป แอฟริกา ฯลฯ — เดิมได้ภาษาอังกฤษ
        if lang in ("en", "es") and not a["crisis"]:
            from core.world_replies import world_lang, compose_world
            wl = world_lang(text)
            if wl and (lang == "en" or wl != "es"):
                out = compose_world(wl, "general", status_line(a, wl) or status, sign, footer)
                if out:
                    return out
        # ไม่เข้าหัวข้อใด — ดูเจตนาก่อนให้คำตอบกลาง ("goodnight" "my mom is not ok" "i want to wake up early")
        it = _intent.detect(text) if (lang == "en" and not a["crisis"] and not a["topics"] and a["text_risk"] < 35) else None
        if it in _intent.SHORT["en"]:
            return f"{_intent.SHORT['en'][it]}\n\n{sign}" + ("\n· Answered from the system's equations — no AI used" if footer else "")
        if it in _intent.STEPS["en"]:
            o, ps, q = _intent.STEPS["en"][it]
            return (o + f"\n\n{status}\n\n" + "\n".join(f"{i + 1}) {p}" for i, p in enumerate(ps))
                    + f"\n\n{q}\n\n{sign}" + ("\n· Answered from the system's equations — no AI used" if footer else ""))
        return compose_intl(lang, a["crisis"], status, sign, footer)

    # ── ถามถึงที่มาของระบบ (core/creator_story — ไม่มีชื่อหรือวันเกิดของผู้สร้าง) ──
    if not a["crisis"] and not a["topics"]:
        try:
            from core.creator_story import detect_creator_question, CREATOR_STORY_TH
            if detect_creator_question(text):
                return CREATOR_STORY_TH.strip() + f"\n\n{sign}" + tag
        except Exception:
            pass

    # ── 1. วิกฤต: ชีวิตมาก่อนทุกอย่าง — ไม่วิเคราะห์ ไม่ให้ตัวเลือกยาว ──
    if a["crisis"]:
        return (
            "ฉันได้ยินสิ่งที่คุณพูดนะคะ และดีใจที่คุณพิมพ์มา\n\n"
            f"ตอนนี้ขอแค่ 2 อย่าง:\n"
            f"1) โทร {HOTLINE_MENTAL} — สายด่วนสุขภาพจิต ฟรี 24 ชั่วโมง มีคนพร้อมฟังโดยไม่ตัดสิน\n"
            f"2) ไปอยู่ใกล้คนอื่น หรือบอกใครสักคนว่าตอนนี้ไม่ไหว — ไม่ต้องอธิบายเหตุผล\n\n"
            f"ถ้ากำลังจะทำร้ายตัวเอง หรือทำไปแล้ว โทร {HOTLINE_EMS} ทันที\n\n"
            "ความรู้สึกตอนนี้หนักมาก แต่มันไม่ใช่ทั้งหมดของคุณ — คุณยังมีทางเลือกอยู่ "
            "พิมพ์ต่อได้เสมอ ฉันอยู่ตรงนี้ค่ะ\n\n— LYLA ◈" + tag
        )

    # ── 2. ทักทายสั้นๆ ─────────────────────────────────────────────
    if not a["topics"] and a["text_risk"] < 35 and len(t.strip()) <= 24 and _hit(t, GREETINGS):
        return (f"สวัสดี{end} เล่าเรื่องที่กำลังตัดสินใจ หรือสิ่งที่หนักใจอยู่มาได้เลย "
                f"ระบบจะช่วยเรียงทางเลือกที่มีให้เห็นชัดขึ้น{end}\n\n{sign}" + tag)

    # ── 2.4 อยากเปลี่ยนคนอื่น → กลับมาที่สิ่งที่ผู้ใช้ควบคุมได้ (ไม่ใช่วิกฤต · ความเสี่ยงต่ำ) ───────────────
    if not a["crisis"] and a["text_risk"] < 50 and CHANGE_OTHER.search(t) and not _HARM_OTHER.search(t) and not _TITAN_POWER.search(t) and not _TITAN_EXIT.search(t):
        return CHANGE_OTHER_TH + f"\n\n{sign}" + tag

    # ── 2.5 คุยเล่น/ขอบคุณ/ฝันดี — เดิมได้ "ขอเรียงเรื่องนี้ให้เห็นเป็นขั้นก่อน" ───────
    chat = small_talk(text) if a["topics"] in ([], ["positive"]) else None
    if chat:
        say = {
            "thanks": f"ยินดีเลย{end} ถ้ามีเรื่องไหนอยากคิดต่อหรืออยากเล่าอีก พิมพ์มาได้ตลอดนะ",
            "night": f"ฝันดีนะ{end} พักให้เต็มที่ เรื่องที่ค้างอยู่ พรุ่งนี้ค่อยว่ากันต่อได้",
            "laugh": f"ดีใจที่ได้ยินเสียงหัวเราะ{end} มีอะไรเล่าต่อไหม",
            "who": (f"{'ผม' if vega else 'ฉัน'}คือ {'VEGA' if vega else 'LYLA'} ผู้ช่วยของ KING DIADEM — เป็น AI ไม่ใช่คน{end} "
                    "ช่วยฟังเรื่องที่หนักใจ เรียงทางเลือก และบอกว่าทางไหนยังเหลือทางถอย "
                    f"แต่ไม่ใช่แพทย์หรือทนาย เรื่องด่วนจะบอกเบอร์ที่ช่วยได้จริงให้{end}"),
            "bored": (f"ช่วงว่างๆ แบบนี้ก็ดีนะ{end} อยากใช้เวลานี้ทำอะไรสักอย่าง หรืออยากคิดเรื่องไหนให้ชัดขึ้น "
                      "เล่ามาได้เลย · ถ้าเบื่อจนไม่อยากทำอะไรมาหลายวันแล้ว บอกได้เหมือนกัน"),
        }[chat]
        return f"{say}\n\n{sign}" + tag

    # ── 2.6 ไม่เข้าหัวข้อใด: ดูเจตนาก่อนให้คำตอบกลาง (core/intent.py) ─────────────
    it = _intent.detect(text) if (not a["topics"] and a["text_risk"] < 35) else None
    if it in _intent.SHORT["th"]:
        return _intent.SHORT["th"][it].format(end=end) + f"\n\n{sign}" + tag

    # ── 3. หัวข้อ → ทาง (หลัก 2–3 ทาง + หัวข้อรอง 1 ทาง) ───────────
    lib = {name: d for name, _, d in TOPICS}
    if it in _intent.STEPS["th"]:
        _o, _ps, _q = _intent.STEPS["th"][it]
        main = {"open": [_o], "paths": list(_ps), "ask": _q}
    else:
        main = lib.get(a["topics"][0]) if a["topics"] else GENERAL
    if a["topics"] and a["topics"][0] == "money" and "job" in a["topics"] and not MONEY_SHORT.search(text) \
            and not re.search(r"ซื้อ|ผ่อน|เก็บเงิน|ออม|โบนัส|เงินก้อน", text):
        main = lib["job"]                      # "อยากเปลี่ยนงาน แต่กลัวเงินเดือนลด" เป็นเรื่องงาน ไม่ใช่แผนเก็บเงิน
    elif a["topics"] and a["topics"][0] == "money" and _money_plan(text):
        main = MONEY_PLAN
    second = lib.get(a["topics"][1]) if len(a["topics"]) > 1 else None
    # เรื่องฉุกเฉิน/เปราะบาง: ขั้นของเรื่องนั้นต้องครบ ไม่แบ่งที่ให้หัวข้อรอง
    # (เดิม "กินยาเกินขนาด" เสียขั้นที่ 3 ให้ "ใช้สิทธิ์บัตรทอง")
    if a["topics"] and a["topics"][0] in _URGENT_TOPICS + ("adult_invite", "grief", "labor", "resign_block", "child_gaming", "consumer", "pet_hurt", "stranded", "teen_leave", "housing", "legal", "diagnosis",
                                                           "caregiver", "health_rights", "preg_alone", "preg_care") + _KP.NAMES:
        second = None
    # เลนส์ปัญหา (core/problem_lens.py) — ตัดสินครั้งเดียว: ไม่ใช่วิกฤต · ความเสี่ยงต่ำกว่า 75 (หนี้ที่ "กลัวโดนยึด" ได้ 60 เคยถูกกันออก)
    # · หัวข้อด่วนต้องไม่มี เว้นแต่เลนส์ประกาศว่ารับแทนได้ (over) และ `no` ของเลนส์กันกรณีที่ด่วนจริงไว้แล้ว
    _lz = _lens.find(text, "th", voice_mode) if (not a["crisis"] and a["text_risk"] < 85) else None
    _urg = set(a["topics"]) & set(_URGENT_TOPICS)
    _lz_ok = bool(_lz) and not (a["topics"] and a["topics"][0] in _KP.NAMES) and _urg <= set(_lz.get("over") or ()) \
        and (a["text_risk"] < 75 or bool(_lz.get("over")))     # 75–84 เฉพาะเลนส์ที่ประกาศรับเรื่องด่วนแทน (รถชนเล็กน้อยได้ 75)
    if _lz_ok and _urg:                  # เลนส์ที่รับเรื่องด่วนแทนได้ มาก่อนคำตอบด่วนแบบทั่วไป
        main, second = _lz, None
    elif a["offer_flags"]:               # ข้อเสนอที่มีโครงสร้างของการหลอก มาก่อนหัวข้ออื่น
        main, second = OFFER, None
    elif "recovery" in (a["scam"] or []):  # หลอกซ้ำ: เสนอตามเงินคืนแลกค่าธรรมเนียม — มาก่อน "โดนโกงแล้ว"
        main, second = SCAM_RECOVERY_D, None
    elif a["scam"] == ["lost"]:          # ถูกโกงไปแล้ว: ตามเงินคืนก่อน
        main, second = SCAM_LOST, None
    elif a["scam"] and set(a["scam"]) <= {"job", "lost"}:    # งานหลอก/ค้ามนุษย์
        main, second = SCAM_JOB_D, None
    elif a["scam"] and set(a["scam"]) <= {"romance", "lost"}:  # หลอกให้รัก/แอบอ้างเป็นเพื่อน
        main, second = SCAM_ROMANCE_D, None
    # ถูกหลอกเปิดบัญชีม้า: ผู้ใช้ต้องรีบระงับบัญชีและแจ้งความ ไม่ใช่ถูกเตือนเรื่องหาเงินไม่สุจริต
    elif _magga_topic(text) and not set(a["topics"]) & {"harm_others", "kp_money_mule"}:
        main, second = _MAGGA_D[_magga_topic(text)], None    # มรรค 8: โกหก/ทุจริต/อยากเอาคืน — ทักตรงๆ ก่อนคำตอบทั่วไป
    elif CODE_REQ.search(text) and a["text_risk"] < 60:
        main, second = CODE_D, None                           # ขอให้เขียน/แก้โค้ด — บอกตรงๆ ว่าไม่ใช่งานถนัด แล้วชวนกลับมาที่การตัดสินใจ
    elif _lz_ok:
        # เลนส์ปัญหา (core/problem_lens.py): อ่านให้ถูกว่าเป็นปัญหาของใคร แก่นคืออะไร เพราะอะไร ก่อนให้ขั้นตอน
        # เดิม "แม่ป่วยติดเตียง ต้องลาออกมาดูแล" ได้คำตอบเรื่องไข้สูง · "พ่อติดเหล้า เมาแล้วด่าแม่" ได้วิธีเลิกเหล้า
        main, second = _lz, None
    elif _everyday(text, a["topics"]) and a["text_risk"] < 60 and not set(a["topics"]) & set(_URGENT_TOPICS) \
            and not (a["topics"] and a["topics"][0] in _KP.NAMES):
        main, second = _everyday(text, a["topics"]), None                  # เรื่องบ้านๆ–ระดับโลกที่เคยได้คำตอบกลาง (EVERYDAY)
    elif _dharma_answer(text) and a["text_risk"] < 60:
        main, second = _dharma_answer(text), None             # ถามความหมายธรรมะ (DHARMA)
    elif re.search(r"(?:เด็ก|คน|ป้า|ลุง|ผู้หญิง|ยาย)ข้างบ้าน[^\n]{0,12}?(?:โดน|ถูก)\S{0,6}?(?:ตี|ทำร้าย|ทุบ|ตบ|ทิ้ง|ขัง)", text) \
            or _WITNESS_SOUND.search(text):
        # "ห้องข้างๆ มีเสียงผู้หญิงกรีดร้องให้ช่วยด้วย" เคยได้ "ขอเรียงเรื่องนี้ให้เห็นเป็นขั้นก่อน" (คลังปัญหา รอบทดสอบประโยคใหม่)
        main, second = lib["witness"], None    # เดิมได้ "ความปลอดภัยของคุณมาก่อน" — ผู้ใช้เป็นคนได้ยิน ไม่ใช่ผู้ถูกทำร้าย
    elif _OTHER_HARM.search(text):
        main, second = OTHER_HARM, None        # "พี่สาวอยากฆ่าแฟน" เคยได้ "ขอบคุณที่พูดออกมาแทนที่จะทำ" เหมือนผู้ใช้เป็นคนโกรธเอง
    elif _FAMILY_WITNESS.search(text):
        # "พ่อเมาแล้วตีแม่ทุกคืน" เคยได้ "ความปลอดภัยของคุณมาก่อน · บาดเจ็บโทร 1669" — ผู้ใช้คือลูกที่เห็นเหตุการณ์
        main, second = FAMILY_WITNESS, None
    elif re.search(r"(?:ลูก|หลาน)[^\n]{0,8}?(?:โดน|ถูก)ครู[^\n]{0,8}?(?:ตี|ทำร้าย|ตบ|ลงโทษ|หยิก|ด่า)", text):
        # "ลูกโดนครูตี" เคยได้ "ความปลอดภัยของคุณมาก่อน · ออกไปอยู่ที่ที่มีคนอื่นแล้วโทร 191" — ผู้ใช้คือพ่อแม่ ไม่ใช่ผู้ถูกทำร้าย
        main, second = TEACHER_HARM, None
    elif a["relationship"] in ("collapse_risk", "critical"):   # ถูกทำร้าย/ควบคุม: ความปลอดภัยมาก่อน
        main, second = SAFETY, None
    elif a["disaster"] and not _person_first(text, a):   # กำลังเจอภัย: ขั้นแรกของภัยนั้นมาก่อน — ยกเว้นมีคนไม่หายใจ/เด็กหายใจไม่ออก
        main, second = {"open": [DISASTER_OPEN], "paths": a["disaster"]["steps"],
                        "ask": a["disaster"].get("ask") or DISASTER_ASK}, None
    elif set(a["topics"]) <= {"decision", "health", "family"}:
        # สัตว์เล็ก/เผาไร่/ทิ้งของเสีย — เดิมทางเลือกไปอยู่ท้ายคำตอบ ใต้ "เขียนสิ่งที่เกิดขึ้นเป็นประโยคเดียว" (รอบหาบั๊ก 8)
        try:
            _d = bridge_analyze(text)["data"]
        except Exception:
            _d = {}
        if (_d.get("disaster") or {}).get("after"):     # หลังน้ำลด — ขั้นหลังภัยเป็นทางหลัก ไม่ใช่ "เขียนเป็นประโยคเดียว"
            main, second = {"open": ["น้ำลดแล้วคือช่วงที่ต้องระวังอีกแบบ — ไฟ โรค และการขอความช่วยเหลือ"],
                            "paths": _d["disaster"]["steps"], "ask": "ตอนนี้ทุกคนในบ้านมีที่พักและน้ำสะอาดใช้แล้วหรือยัง?"}, None
        elif (_d.get("earth") or {}).get("steps"):
            e = _d["earth"]
            main, second = {"open": [f"เรื่อง{e['name']}มีทาง{'ที่ไม่ต้องทิ้งลงน้ำ' if e.get('kind') == 'water_dumping' else 'ที่ไม่ต้องเผา'} และหลายทางประหยัดกว่าด้วย" if e["self"]
                                     else "ควันหรือของเสียจากคนอื่นกระทบคุณได้ — ป้องกันตัวเองก่อน แล้วค่อยแจ้ง"],
                            "paths": e["steps"], "ask": "ทางไหนที่พอทำได้จริงในพื้นที่ของคุณ?"}, None
        elif (_d.get("animal") or {}).get("steps"):
            an = _d["animal"]
            main, second = {"open": ["สัตว์ป่วยมักซ่อนอาการ — ดูแลเร็วดีที่สุด" if an.get("sick")
                                     else "แก้ปัญหาได้โดยไม่ต้องฆ่า — และปลอดภัยกับคนในบ้านกว่า"],
                            "paths": an["steps"], "ask": "ตอนนี้ปัญหาหลักคืออะไร — เข้าบ้าน กัดของ หรือเรื่องสุขภาพ?"}, None

    # อ่านคน (core/person_reading.py · MBTI เป็นตำราเล่มแรก): ข้อความนี้ขอข้อมูลแบบไหน ใช้เหตุผลหรือใจ อยากได้ข้อสรุปไหม
    # ปรับแค่ประโยคเปิดและคำถามปิด ขั้นตอนเหมือนเดิม · ไม่ปรับเรื่องด่วน/เสี่ยงสูง และไม่บอกผู้ใช้ว่าอ่านเขาแบบไหน
    if not a["crisis"] and a["text_risk"] < 75 and not (set(a["topics"]) & set(_URGENT_TOPICS)) and voice_mode != "council":
        main = _person.adapt_main(main, _person.read(text), "th")

    paths = _paths(main, t)[:3]
    if second:
        extra = _pick(_paths(second, t)[:2], text, "2nd")
        if extra and extra not in paths:
            paths = paths[:2] + [extra]
    # เรื่องด่วนมีขั้นของตัวเองครบแล้ว — ไม่แทรกข้อทั่วไปจนขั้นสำคัญ (เช่นเบอร์สายด่วน) ถูกดันตก
    urgent_main = bool(a["topics"]) and a["topics"][0] in _URGENT_TOPICS
    if route == "survival" and not urgent_main and not a["disaster"] and "basic" not in a["topics"] and not any("กิน" in p for p in paths):
        paths.insert(0, "ดูแลร่างกายก่อน: กิน นอน ดื่มน้ำ และอยู่ในที่ปลอดภัย — ตัดสินใจเรื่องใหญ่หลังจากนั้น")
    if route == "collapse" and a["topics"] and not urgent_main and a["topics"][0] not in ("violence", "health_emergency", "basic"):
        paths.insert(0, "หยุดสิ่งที่ทำให้เสียหายเพิ่มก่อน (Stop the line) — ยังไม่ต้องหาทางชนะ ขอแค่ไม่แย่ลง")

    # ── ตัวเลือกที่ผู้ใช้ให้มา: วัดด้วย Choice(t+1) ──────────────────
    # เรื่องฉุกเฉินไม่เทียบทางเลือก — "กินยาไป 30 เม็ด จะไปโรงพยาบาลหรือนอนเฉยๆ" เคยได้ "นอนเฉยๆ — ย้อนกลับได้"
    opts = a["options"] if not council_unsuitable(a) else []
    opt_block = ""
    if len(opts) >= 2:
        letters = "ABCDEFG"
        # เรียงด้วย ENGINE/choice_optimizer — W ต่ำ ทางที่ย้อนกลับได้ได้เปรียบ
        ranked = rank_options(opts, waterline=a["W"])
        rows = "\n".join(f"{letters[i]} · {r['action'][:80]} — "
                          f"{'ย้อนกลับได้' if r['reversible'] else 'ย้อนกลับยาก'}"
                          for i, r in enumerate(ranked))
        opt_block = ("\n\nเทียบตัวเลือกของคุณ (เรียงจากรอดที่สุด):\n" + rows +
                     "\n→ เลือกทางที่ Choice(t+1) มากกว่า: ย้อนกลับได้ ชนะ ย้อนกลับไม่ได้ (ถ้าผลพอๆ กัน)")

    # ── เงิน: เวลาที่มีจริง = เงิน ÷ รายจ่ายจำเป็นต่อวัน ─────────────
    # ── ตัวเลขจากเรื่องของผู้ใช้: หนี้ · เวลาที่มีจริง · ความสัมพันธ์ (core/engine_bridge) ──
    bridge = bridge_analyze(text) if not a["offer_flags"] else {"lines": [], "data": {}}
    # ขั้นของภัย/ทางเลือกสัตว์-เผาไร่อยู่ในรายการหลักแล้ว — ไม่พิมพ์ซ้ำ (รวมบรรทัดสรุปที่มีข้อเดียวกันอยู่ข้างใน)
    shown = [l for l in bridge["lines"] if l not in paths and not any(len(p) > 20 and p in l for p in paths)]
    calc_block = ("\n\nจากสิ่งที่คุณเล่า:\n" + "\n".join("· " + l for l in shown)) if shown else ""

    # เฉพาะเงินที่ "มีอยู่" จริง (เงินเก็บ เงินสำรอง) — เดิมใช้ตัวเลขเงินตัวแรกในข้อความ:
    # "เงินเดือน 15,000" "ค่าเช่า 5,000" "รถราคา 800,000" กลายเป็นเงินคงเหลือ ≈ 100 / 33 / 5,333 วัน
    money_line = ""
    cash = _cash_on_hand(text)
    if cash and not a["offer_flags"] and not _SPENT.search(t) and "runway" not in bridge["data"] and "debt" not in bridge["data"] and "business" not in bridge["data"] and "business" not in a["topics"]:
        monthly = _monthly_expense(text)
        per_day = round(monthly / 30) if monthly else 150
        money_line = (f"\n\nเวลาที่มีจริง = เงิน ÷ รายจ่ายจำเป็นต่อวัน → {cash:,.0f} ÷ {per_day:,} ≈ {cash / per_day:,.0f} วัน"
                      + (f" (≈ {cash / monthly:,.1f} เดือน จากรายจ่ายที่คุณบอก)" if monthly
                         else f" (ตัวอย่างที่วันละ {per_day} บาท — ใส่ตัวเลขจริงของคุณแทนได้)"))

    # Canon มาตรา 11: Options ≤ 3 — เดิม [:4] เส้นทาง survival/collapse จึงเสนอ 4 ทาง · Choice(t) ≥ 1 เสมอ
    paths = paths[:3] or GENERAL["paths"][:1]
    body = "\n".join(f"{i + 1}) {p}" for i, p in enumerate(paths))
    opener = _pick(main["open"], text, "open")
    if a["offer_flags"]:
        opener = ("ข้อเสนอนี้มีสัญญาณที่พบบ่อยในการหลอกลงทุน/แชร์ลูกโซ่: "
                  + " · ".join(OFFER_FLAG_TH[f] for f in a["offer_flags"])
                  + f" — ความตื่นเต้นเป็นเรื่องปกติ{end} แต่ข้อเสนอแบบนี้ต้องชะลอก่อนตอบ")
    status = status_line(a)

    return (f"{opener}\n\n{status}\n\n{body}{calc_block}{opt_block}{money_line}\n\n"
            f"คำถามเดียวที่ควรถามตัวเองตอนนี้: {main['ask']}\n\n{sign}" + tag)



# "อยากตาย 555" / "I want to die 😂" — มักพูดเล่น แต่บางคนใช้หัวเราะกลบความจริง
# จึงยังให้เบอร์ช่วยเหลือครบเหมือนเดิม เปลี่ยนแค่ประโยคเปิดให้ถามไถ่เบาๆ ไม่ตกใจใส่
_JOKE_MARK = re.compile(r"5{3,}|ฮ่า{2,}|ขำ|😂|🤣|😆|😅|\b(?:lol|lmao|haha+|jk)\b", re.I)
_SERIOUS_MARK = re.compile(r"เม็ด|เชือก|กระโดด|ตึก|มีด|กรีด|ปืน|จดหมาย|ลาก่อน|คืนนี้|วันนี้แหละ|"
                           r"pills?|rope|jump|bridge|knife|cut|gun|goodbye|tonight|note|plan", re.I)
_SOFT_OPEN = {
    "ฉันได้ยินสิ่งที่คุณพูดนะคะ และดีใจที่คุณพิมพ์มา":
        "อ่านแล้วเหมือนพูดขำๆ นะคะ แต่ขอถามจริงๆ สักนิด — ช่วงนี้เหนื่อยหรือหนักใจอยู่หรือเปล่า "
        "ถ้าแค่ล้อเล่นก็ไม่เป็นไรเลย แต่ถ้ามีส่วนไหนที่จริงอยู่ เก็บข้อความนี้ไว้นะคะ",
    "I hear you, and I'm glad you wrote to me.":
        "That sounds like it might be a joke — and if it is, that's okay. But I want to check gently: "
        "are things feeling heavy lately? If any part of it is real, please keep this:",
}


_CANT_GO_ON = re.compile(r"\bi\s+can'?t\s+(?:do|take|handle|keep doing)\s+(?:this|it)\s+any\s?more\b", re.I)
_CANT_OPEN = ("I hear how worn out you are — thank you for saying it. When you say you can't do this anymore, "
              "I want to gently check: do you mean you're exhausted, or are thoughts of not wanting to be here part of it too?")
_WORK_OPEN = {
    "ขอบคุณที่บอกให้ชัดนะ — เข้าใจแล้ว และดีใจที่เล่าให้ฟัง":
        "เรื่องนี้หนักแม้จะเป็นงานเขียนหรืองานค้นคว้า — ยินดีช่วยนะ และขอฝากไว้เผื่อระหว่างทำแล้วรู้สึกหนักใจเอง",
    "Thanks for making that clear — got it, and I'm glad you told me.":
        "Happy to help with the work — it's a heavy subject, so I'll leave a few things here in case it ever feels personal.",
}


