# โกรธจนตัวสั่น/อยากทุบพัง (core/second_layer.ANGER_MOOD) — คำตอบชวนพักก่อนลงมือ แทนคำถามว่าเหนื่อยจากอะไร
_ANGER_REPLY = {
    "th": ("ความโกรธแรงขนาดนี้ ร่างกายก็รับไว้เต็มๆ เลยนะคะ — ตอนนี้ยังไม่ต้องทำอะไร ขอพักสักครู่ก่อน",
           ["ออกห่างจากคนหรือของที่ทำให้โกรธก่อน ไปอีกห้องหรือออกไปเดินข้างนอกสัก 10 นาที",
            "กำมือแน่นแล้วคลาย ทำซ้ำสักสองสามครั้ง แล้วหายใจออกให้ยาวกว่าหายใจเข้า หัวใจจะค่อยๆ ช้าลง",
            "รอให้ใจเย็นก่อนค่อยตัดสินใจว่าจะพูดหรือทำอะไร ถ้ารู้สึกว่าจะคุมตัวเองไม่อยู่ โทร 1323 คุยได้ตลอด 24 ชม."],
           "ตอนนี้โกรธใครหรือเรื่องอะไรอยู่คะ แล้วมีใครอยู่ใกล้ๆ ที่อาจโดนลูกหลงไหม"),
    "en": ("Anger this strong hits the whole body — you don't have to do anything right now. Let's pause first.",
           ["Step away from the person or thing that set it off — another room or a walk outside for about 10 minutes.",
            "Clench your fists hard and release a few times, then breathe out longer than you breathe in — your heart rate will come down.",
            "Decide what to say or do only once you've cooled down. If you feel you might lose control, a crisis line can talk it through any time (1323 in Thailand, 988 in the US)."],
           "Who or what are you angry at right now — and is anyone nearby who could get caught in it?"),
}


def _anger_reply(text, out):
    from core.second_layer import ANGER_MOOD, ANGER_NOT
    if not (ANGER_MOOD.search(text) and not ANGER_NOT.search(text)):
        return None
    parts = out.split("\n\n")
    i = next((k for k, x in enumerate(parts) if x.startswith("1) ")), None)
    if i is None or i + 1 >= len(parts):
        return None
    lang = "th" if re.search(r"[\u0E00-\u0E7F]", parts[0]) else "en"
    opener, steps, ask = _ANGER_REPLY[lang]
    label = parts[i + 1].split(": ", 1)[0] + ": " if ": " in parts[i + 1] else ""
    parts[0] = opener
    parts[i] = "\n".join(f"{n + 1}) {x}" for n, x in enumerate(steps))
    parts[i + 1] = label + ask
    return "\n\n".join(parts)


def _soften_joking_crisis(text, out):
    try:
        if isinstance(out, str) and isinstance(text, str) and out.startswith(
                tuple(_HEAVY_OPEN) + tuple(_HEAVY_OPEN.values())):
            ang = _anger_reply(text, out)
            if ang:
                return ang
    except Exception:
        pass
    try:
        from core.second_layer import HEAVY_MOOD as _HM
        if isinstance(out, str) and isinstance(text, str) and _HM.search(text):
            for plain, heavy in _HEAVY_OPEN.items():
                if out.startswith(plain):
                    return heavy + out[len(plain):]
    except Exception:
        pass
    if isinstance(out, str) and isinstance(text, str) and _CANT_GO_ON.search(text) \
            and out.startswith("Thanks for making that clear — got it, and I'm glad you told me."):
        return _CANT_OPEN + out[len("Thanks for making that clear — got it, and I'm glad you told me."):]
    if isinstance(out, str) and isinstance(text, str) and _WORK_FRAME.search(text) and not _SELF_REF.search(text):
        for plain, work in _WORK_OPEN.items():
            if out.startswith(plain):
                return work + out[len(plain):]
    if not isinstance(out, str) or not _JOKE_MARK.search(text or "") or _SERIOUS_MARK.search(text or ""):
        return out
    for hard, soft in _SOFT_OPEN.items():
        if out.startswith(hard):
            return soft + out[len(hard):]
    return out


# อยากเปลี่ยนคนอื่น ("ทำยังไงให้แฟนเลิกเล่นเกม" · "how do I make my husband stop drinking")
# หลักของเจ้าของโปรเจกต์: "ห้ามแทรกแซงชีวิตใด หากเจ้าของปัญหายังไม่แสดงเจตจำนงอยากเปลี่ยน" — เปลี่ยนใครแทนเขาไม่ได้
# จึงพากลับมาที่สิ่งที่ผู้ใช้ควบคุมได้: สิ่งที่ตัวเองพูด ขอบเขตที่ตั้งได้ และเส้นที่ต้องปกป้องตัวเอง (ไม่สอนวิธีบังคับหรือหลอกคนอื่น)
_WHO_TH = r"(?:แฟน|สามี|ภรรยา|เมีย|ผัว|แม่|พ่อ|ลูก|พี่|น้อง|เพื่อน|หัวหน้า|เจ้านาย|ญาติ|ยาย|ย่า|ตา|ปู่|คนรัก|เขา|เธอ)"
_WHO_EN = r"(?:my |our )?(?:partner|husband|wife|boyfriend|girlfriend|bf|gf|mom|mother|dad|father|parents?|son|daughter|kids?|brother|sister|friend|boss|manager|coworker|him|her|them)"
CHANGE_OTHER = re.compile(
    r"(?:ทำ(?:ยังไง|อย่างไร|ไง)(?:ดี)?ให้|อยากให้|จะให้|ทำให้|บังคับให้|เปลี่ยน)\s*" + _WHO_TH + r"\S{0,4}\s*(?:เลิก|หยุด|เปลี่ยน|ยอม|กลับมา|ฟัง|เข้าใจ|ดีขึ้น|ไม่)|"
    r"(?:how (?:do|can|could|should) i|ways? to|help me) (?:make|get|force|change|convince|stop) " + _WHO_EN + r"\b|"
    r"(?:change|fix) " + _WHO_EN + r"\b", re.I)
# มีการทำร้าย/ข่มขู่ = เรื่องความปลอดภัย ไม่ใช่เรื่อง "เปลี่ยนเขาไม่ได้" — ห้ามเข้าทางนี้ (ปล่อยให้ทางความปลอดภัยตอบ)
# เคยพบ: "how do I make my bf stop hitting me" ความเสี่ยงต่ำกว่า 50 จึงได้คำตอบเรื่องตั้งขอบเขต ทั้งที่ต้องได้เรื่องความปลอดภัย
_HARM_OTHER = re.compile(r"ตบ|ตี|ต่อย|ทำร้าย|ข่มขู่|ขู่|ทุบ|บีบคอ|ลวนลาม|ข่มขืน|ทารุณ|"
                         r"\b(?:hit|hits|hitting|beat|beats|beating|hurt|hurts|hurting|abuse|abuses|abusing|abusive|choke|choking|threaten|threatens|rape|kick|kicks|punch|punches|slap|slaps)\b", re.I)
CHANGE_OTHER_TH = ("เปลี่ยนใครแทนเขาไม่ได้ — คนจะเปลี่ยนเมื่อเขาอยากเปลี่ยนเอง แต่คุณยังมีสิ่งที่ทำได้จริง:\n"
                   "1) บอกความรู้สึกของคุณครั้งเดียวให้ชัด แบบไม่ตำหนิ: \"ฉันรู้สึก… เวลาที่… ฉันอยากให้…\"\n"
                   "2) ตั้งขอบเขตของคุณเอง — สิ่งที่คุณจะทำ ถ้าเรื่องเดิมยังเกิดขึ้น (ไม่ใช่คำขู่ แต่เป็นการดูแลตัวเอง)\n"
                   "3) ถ้าเรื่องนี้ทำให้คุณไม่ปลอดภัย หรือเงิน/สุขภาพของคุณเสียหาย ความปลอดภัยของคุณมาก่อนความสัมพันธ์เสมอ\n\n"
                   "อยากเล่าเพิ่มไหมว่าเรื่องนี้กระทบตัวคุณยังไงบ้าง?")
CHANGE_OTHER_EN = ("You can't change someone for them — people change when they want to. What you can do:\n"
                   "1) Say how it affects you once, clearly and without blame: \"I feel… when… I'd like…\"\n"
                   "2) Set your own boundary — what you will do if it keeps happening (not a threat, a way of looking after yourself).\n"
                   "3) If it puts your safety, money or health at risk, your safety comes before the relationship.\n\n"
                   "Do you want to tell me more about how this is affecting you?")


