_PATICCA_SAY = {
    "craving": "ต้นเหตุที่เห็นคือความอยากได้ — ความรู้สึกดีตอนนี้ไม่ได้แปลว่าทางนี้ดี ลองแยกข้อเท็จจริงออกจากความหวัง",
    "fear": "ต้นเหตุคือความกลัว — แยกให้ชัดว่าสิ่งที่กลัวเกิดขึ้นจริงแล้ว หรือยังเป็นแค่ความเป็นไปได้",
    "aversion": "ต้นเหตุคือความอยากผลักสิ่งที่ไม่ชอบออกไป — ถามตัวเองว่ากำลังหนีจากอะไร และอยากไปหาอะไร",
    "clinging": "ต้นเหตุคือความยึดติด กลัวเสีย — ถ้าเริ่มจากศูนย์วันนี้ จะยังเลือกแบบเดิมไหม",
    "misinformation": "ข้อมูลอาจผิดหรือถูกหลอก — ตรวจจากแหล่งที่สองก่อนตัดสินใจ",
    "bias": "อาจมีอคติปนอยู่ — ลองหาเหตุผลของอีกฝั่งดูสักข้อ",
}
# CIVIL ⬡ — แรงกระเพื่อม: ใครอยู่ในเรื่องนี้ด้วย และใครช่วยแบกได้
_CIVIL_PEOPLE = ((r"ลูก(?!ค้า|น้อง|ชิ้น|อม|เตะ|บอล|ศิษย์|หนี้|จ้าง)", "ลูก"), (r"พ่อ(?!ค้า)|แม่(?!ค้า|น้ำ|บ้าน)", "พ่อแม่"),
                 (r"แฟน(?!บอล|คลับ|เพจ)", "แฟน"), (r"สามี|ภรรยา|ผัว|เมีย", "คู่ชีวิต"), (r"ครอบครัว|ที่บ้าน", "ครอบครัว"),
                 (r"(?<!รุ่น)(?:พี่|น้อง)(?!ชาย|สาว)?", "พี่น้อง"), (r"เพื่อน", "เพื่อน"), (r"ลูกน้อง|ทีม|ลูกจ้าง", "ทีม"),
                 (r"ลูกค้า", "ลูกค้า"), (r"หุ้นส่วน", "หุ้นส่วน"), (r"หมา|แมว|สัตว์เลี้ยง", "สัตว์ที่เลี้ยง"))
_IRREVERSIBLE = re.compile(r"ลาออก|กู้|ลงทุน|ขาย(?:บ้าน|รถ|ที่ดิน)|จำนอง|ค้ำประกัน|ย้ายประเทศ|หย่า|\b(?:quit|loan|invest|mortgage)\b", re.I)
_CIVIL_ALONE = re.compile(r"ไม่มีใคร|อยู่คนเดียว|ตัวคนเดียว|ไม่มีเพื่อน|ไม่กล้าบอกใคร|ไม่อยากให้ใครรู้|\balone\b|no one", re.I)


def _civil_voice(text: str, risky: bool, reversible: bool = True) -> tuple[str, str]:
    """คืน (ข้อความ, โหวต) — มองว่าการตัดสินใจนี้กระทบใคร และใครช่วยแบกได้"""
    if _CIVIL_ALONE.search(text):
        return ("ตอนนี้ดูเหมือนคุณแบกเรื่องนี้อยู่คนเดียว — การตัดสินใจที่ดีมักมาจากคนสองคนขึ้นไป "
                "หาคนหนึ่งคนที่เล่าให้ฟังได้ หรือโทร 1300 (ฟรี 24 ชม.) ก่อนลงมือ", "stabilize")
    who = []
    for pat, label in _CIVIL_PEOPLE:
        if re.search(pat, text) and label not in who:
            who.append(label)
    if who:
        names = " · ".join(who[:3])
        return (f"แรงกระเพื่อมของเรื่องนี้ไปถึง {names} ด้วย — ถามตัวเองว่าทางไหนที่ถ้าพลาด "
                f"พวกเขายังไม่ต้องรับผลหนัก และในนั้นมีใครช่วยแบกส่วนหนึ่งได้บ้าง",
                # มีคนพึ่งเราอยู่ + ทางที่ย้อนกลับยาก (ลาออก กู้ ลงทุน) → ชะลอ ให้คนที่รับผลด้วยได้มีส่วนรู้ก่อน
                "pause" if risky or (not reversible and set(who) & {"ลูก", "คู่ชีวิต", "พ่อแม่"}) else "proceed_small")
    return ("ทุกการตัดสินใจมีคนอื่นอยู่ในนั้นเสมอ — ใครได้ ใครเสียจากทางนี้ "
            "และมีใครสักคนที่ช่วยแบกหรือช่วยดูทางให้คุณได้ไหม", "proceed_small")


_COUNCIL_ACTION_TH = {
    "proceed_small": "เดินหน้าได้ แต่เริ่มแบบเล็กและย้อนกลับได้ก่อน",
    "pause": "ชะลอไว้ก่อน หาข้อมูลเพิ่มอีกนิดแล้วค่อยตัดสินใจ",
    "stabilize": "ทำให้ตัวเองมั่นคงก่อน (กิน นอน ความปลอดภัย เงินสำหรับไม่กี่วัน) แล้วค่อยตัดสินใจเรื่องใหญ่",
}




def council_unsuitable(a: dict) -> bool:
    """เรื่องฉุกเฉินไม่ควรรอ 6 มุมมอง — ให้ขั้นตอนช่วยเหลือทันที"""
    return bool(a.get("crisis") or a.get("disaster") or a.get("relationship") in ("collapse_risk", "critical")
                or (a.get("topics") and a["topics"][0] in _URGENT_TOPICS))


def compose_council(text: str, footer: bool = True) -> str:
    """สภา 6 เสียง: LYLA ใจ · VEGA ความเสี่ยง · PATICCA ต้นเหตุ · TITAN ทางรอดวันนี้ · COSMOS ภาพยาว · CIVIL แรงกระเพื่อม"""
    text = text if isinstance(text, str) else str(text or "")
    a = assess(text)
    if council_unsuitable(a) or detect_lang(text) != "th":
        return compose(text, footer=footer)          # ฉุกเฉิน/ภาษาอื่น: คำตอบที่ปลอดภัยที่สุดมาก่อนสภา
    from core import decision_brief as _db
    if _db.applies(text) and a["text_risk"] < 60 and not a.get("scam") and not a["offer_flags"]:
        return _db.council(text, footer=footer)      # ตัดสินใจเรื่องใหญ่: ทุกเสียงใช้ตัวเลขจริง + เงื่อนไขเดินหน้า/หยุด
    t = text.lower()
    lib = {name: d for name, _, d in TOPICS}
    main = lib.get(a["topics"][0]) if a["topics"] else GENERAL
    if a["offer_flags"]:
        main = OFFER
    elif "recovery" in (a.get("scam") or []):
        main = SCAM_RECOVERY_D
    elif a.get("scam") == ["lost"]:
        main = SCAM_LOST
    elif a.get("scam") and set(a["scam"]) <= {"job", "lost"}:
        main = SCAM_JOB_D
    elif a.get("scam") and set(a["scam"]) <= {"romance", "lost"}:
        main = SCAM_ROMANCE_D
    elif _magga_topic(text) and not set(a["topics"]) & {"harm_others", "kp_money_mule"}:
        main = _MAGGA_D[_magga_topic(text)]
    elif CODE_REQ.search(text) and a["text_risk"] < 60:
        main = CODE_D
    elif a["text_risk"] < 60 and not a["crisis"] and not set(a["topics"]) & set(_URGENT_TOPICS) \
            and not (a["topics"] and a["topics"][0] in _KP.NAMES) and _lens.find(text, "th"):
        main = _lens.find(text, "th")        # สภาก็ต้องอ่านเรื่องให้ถูกก่อน — เดิม "พ่อติดเหล้า" TITAN ให้ผู้ใช้สังเกตการดื่มของตัวเอง
    elif _everyday(text, a["topics"]) and a["text_risk"] < 60 and not set(a["topics"]) & set(_URGENT_TOPICS) \
            and not (a["topics"] and a["topics"][0] in _KP.NAMES):
        main = _everyday(text, a["topics"])
    elif _dharma_answer(text) and a["text_risk"] < 60:
        main = _dharma_answer(text)
    elif a["relationship"] in ("collapse_risk", "critical"):
        main = SAFETY
    paths = _paths(main, t) or GENERAL["paths"]

    # VEGA — Downside ก่อน: ทางเลือกของผู้ใช้เรียงด้วย choice_optimizer
    opts = a["options"]
    if len(opts) >= 2:
        ranked = rank_options(opts, waterline=a["W"])
        irr = [r["action"][:40] for r in ranked if not r["reversible"]]
        vega = ("ความเสี่ยง " + risk_phrase(a) + f" — ทางที่รอดที่สุดคือ \"{ranked[0]['action'][:50]}\""
                + (f" · \"{irr[0]}\" ย้อนกลับยาก ต้องมีเงินสำรองก่อน" if irr else ""))
        reversible_first = ranked[0]["reversible"]
    else:
        vega = ("ความเสี่ยง " + risk_phrase(a) + f" — ถามก่อนว่าถ้าพลาดจะเสียอะไร และถอยกลับได้ไหม "
                "ทางที่ย้อนกลับได้ชนะ ถ้าผลพอๆ กัน")
        reversible_first = True
    if main.get("vega") and len(opts) < 2:
        vega = "ความเสี่ยง " + risk_phrase(a) + " — " + main["vega"]     # เลนส์ปัญหา: โครงสร้างของเรื่องนี้ แทนคำถามกลาง
    if a["offer_flags"]:
        vega = ("ความเสี่ยง " + risk_phrase(a) + f" — ข้อเสนอนี้มีสัญญาณของการหลอก: "
                + " · ".join(OFFER_FLAG_TH[f] for f in a["offer_flags"]) + " — ลงเงินแล้วอาจถอยไม่ได้")

    # PATICCA — ต้นเหตุจากข้อความ (ENGINE/paticcasamuppada_engine)
    root = {}
    try:
        from ENGINE.paticcasamuppada_engine import detect_root_cause
        root = detect_root_cause(text) or {}
    except Exception:
        pass
    has_root = root.get("evidence", True) and root.get("root") in _PATICCA_SAY
    paticca = (_PATICCA_SAY[root["root"]] if has_root else
               "จากที่เล่ายังไม่เห็นต้นเหตุชัด — เรื่องนี้เริ่มจากอะไร ก่อนจะเป็นแบบนี้เกิดอะไรขึ้น")

    lyla = _pick(main["open"], text, "council")
    titan = paths[0]
    cosmos = main["ask"]

    # มติ: ให้แต่ละเสียงโหวตจากหลักฐานของตัวเอง แล้วรวมด้วย AI/council_engine.build_consensus
    risky = a["risk"] >= 55 or bool(a["offer_flags"]) or bool(a.get("scam"))
    votes = {
        "LYLA":    {"action": "stabilize" if risky else "proceed_small", "confidence": 0.6},
        "VEGA":    {"action": "proceed_small" if (reversible_first and not risky) else "pause", "confidence": 0.7},
        "PATICCA": {"action": "pause" if has_root and root["root"] in ("craving", "fear", "misinformation") else "proceed_small",
                    "confidence": 0.6},
        "TITAN":   {"action": "stabilize" if a["risk"] >= 75 else "proceed_small", "confidence": 0.7},
        "COSMOS":  {"action": "pause" if risky else "proceed_small", "confidence": 0.5},
    }
    civil, civil_vote = _civil_voice(text, risky, reversible_first and not _IRREVERSIBLE.search(text))
    votes["CIVIL"] = {"action": civil_vote, "confidence": 0.6}
    verdict, agree = _COUNCIL_ACTION_TH["pause"], ""
    try:
        from AI.council_engine import build_consensus
        c = build_consensus(votes)
        verdict = _COUNCIL_ACTION_TH.get(c["final_action"], verdict)
        top = max(sum(1 for v in votes.values() if v["action"] == c["final_action"]), 1)
        agree = f" (เห็นตรงกัน {top}/{len(votes)})"
    except Exception:
        pass

    if main.get("verdict") and not risky:
        # เลนส์ปัญหาที่เป็น "สถานการณ์" (พ่อเมาด่าแม่ · ถูกบอกเลิก) — เดิมได้มติ "เดินหน้าได้ แต่เริ่มแบบเล็ก" ซึ่งไม่มีอะไรให้เดินหน้า
        verdict, agree = main["verdict"], ""
    tag = "\n· ตอบจากสมการของระบบ — ไม่ได้ใช้ AI" if footer else ""
    return (f"LYLA ◈ — {lyla}\n\nVEGA ◆ — {vega}\n\nPATICCA ☸ — {paticca}\n\n"
            f"TITAN ▲ — ก้าวที่ทำได้ภายใน 24 ชั่วโมง: {titan}\n\nCOSMOS ✦ — {cosmos}\n\nCIVIL ⬡ — {civil}\n\n"
            f"มติสภา{agree}: {verdict}\nคุณเป็นคนตัดสินใจเสมอ\n\n— สภา KING DIADEM ✦" + tag)


# ── ข้อความถัดไปหลังเล่าว่าอยากตาย (ไม่มี AI) ──────────────────────────────────────────
# เดิมต่อข้อความเก่าเข้ากับข้อความใหม่แล้วตอบใหม่ — "ขอบคุณ" "ล้อเล่น" "how do I bake bread" ได้คำตอบวิกฤตครั้งแรกซ้ำคำต่อคำ
# และถ้าเรื่องเดิมเป็นภาษาไทย คำถามภาษาอังกฤษก็ได้คำตอบภาษาไทย
_FOLLOW = {
    "th": ("ขอบคุณที่ยังคุยกันอยู่นะ{q} เมื่อกี้คุณเล่าเรื่องที่หนักมาก ขอถามสั้นๆ ว่าตอนนี้ปลอดภัยไหม{q}",
           "ถ้าความรู้สึกนั้นกลับมาเมื่อไหร่ โทร 1323 (สายด่วนสุขภาพจิต 24 ชม.) ได้ทุกเวลา · ถ้าอันตรายตอนนี้ 1669",
           "อยากเล่าต่อเรื่องไหนก็ได้ ฉันอยู่ตรงนี้{end}", "· ตอบจากสมการของระบบ — ไม่ได้ใช้ AI"),
    "en": ("Thank you for still talking with me. Earlier you shared something really heavy — are you safe right now?",
           "If that feeling comes back, you can reach someone anytime: in Thailand 1323 (mental health, 24h) · 1669 if you're in "
           "danger now · elsewhere findahelpline.com",
           "We can talk about anything you like. I'm here.", "· Answered from the system's equations — no AI used"),
}


def compose_followup(text: str, voice_mode: str = "lyla", footer: bool = True) -> str:
    """ข้อความต่อจากเรื่องอยากตายที่ตัวเองไม่มีความเสี่ยง: ถามว่าปลอดภัยไหม + เบอร์ 1323 สั้นๆ
    ข้อความยาวที่เป็นเรื่องใหม่ได้คำตอบของเรื่องนั้น แล้วต่อท้ายด้วยเบอร์"""
    text = _clip(text)
    lang = "th" if detect_lang(text) == "th" else "en"
    vega = voice_mode == "vega"
    end = ("ครับ" if vega else "ค่ะ") if lang == "th" else ""
    sign = "— VEGA ◆" if vega else "— LYLA ◈"
    ask, line, close, tag = _FOLLOW[lang]
    tag = "\n" + tag if footer else ""
    if len(text.strip()) > 30:
        body = compose(text, voice_mode=voice_mode, footer=False).rstrip()
        if body.endswith(sign):
            body = body[: -len(sign)].rstrip()
        return f"{body}\n\n{line}\n\n{sign}{tag}"
    q = ("ครับ" if vega else "คะ") if lang == "th" else ""     # คำถาม/นะ ใช้ "คะ" ไม่ใช่ "ค่ะ" ("นะค่ะ" "ไหมค่ะ" สะกดผิด)
    return f"{ask.format(end=end, q=q)}\n\n{line}\n\n{close.format(end=end)}\n\n{sign}{tag}"
